-- Name: set_updated_at(); Type: FUNCTION; Schema: htt; Owner: -
--

CREATE FUNCTION "htt"."set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.updated_at = now();
  return new;
end $$;


