-- Name: COLUMN "access_roles"."archived_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."access_roles"."archived_by" IS 'The person (company_os.people) who retired it; null while it is live or when a migration retired it.';


