--
-- Name: TABLE "account_health_snapshots"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."account_health_snapshots" IS 'One row is: one nightly health reading of one client account. [other · Logs, audit & telemetry | tier 3 support | active]';


--
-- Name: COLUMN "account_health_snapshots"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."account_health_snapshots"."id" IS 'Primary key.';


--
-- Name: COLUMN "account_health_snapshots"."company_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."account_health_snapshots"."company_id" IS 'The client account, referencing companies.id; deleting the company deletes its readings.';


--
-- Name: COLUMN "account_health_snapshots"."taken_on"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."account_health_snapshots"."taken_on" IS 'The business day (Saigon calendar) the reading is for; one row per company per day, the routine upserts.';


--
