);


--
-- Name: affiliates; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."affiliates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "code" "extensions"."citext" NOT NULL,
    "person_id" "uuid",
