    "code_discount" "text",
    "code_commission" "text",
    "referred_by" "text",
    CONSTRAINT "affiliates_party_present_chk" CHECK ((("company_id" IS NOT NULL) OR ("person_id" IS NOT NULL))),
    CONSTRAINT "affiliates_program_type_check" CHECK (("program_type" = ANY (ARRAY['discount'::"text", 'commission'::"text"])))
);


--
-- Name: COLUMN "affiliates"."company_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."affiliates"."company_id" IS 'The affiliate company when this is a company affiliate. person_id (kept) is the acting/portal contact. At least one of company_id/person_id is set.';


--
-- Name: agreements; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."agreements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "company_id" "uuid",
    "deal_id" "uuid",
    "team_member_id" "uuid",
    "vendor_id" "uuid",
    "signer_person_id" "uuid" NOT NULL,
    "signer_title" "text" NOT NULL,
    "filename" "text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "content_type" "text" NOT NULL,
    "sha256" "text" NOT NULL,
    "size_bytes" bigint,
    "fee_amount_cents" bigint,
    "fee_currency" "text",
    "fee_description" "text",
    "prepared_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    "archived_by" "uuid",
    CONSTRAINT "agreements_content_type_check" CHECK (("content_type" = ANY (ARRAY['text/markdown'::"text", 'application/pdf'::"text"]))),
    CONSTRAINT "agreements_fee_amount_cents_check" CHECK ((("fee_amount_cents" IS NULL) OR ("fee_amount_cents" > 0))),
    CONSTRAINT "agreements_fee_currency_check" CHECK ((("fee_currency" IS NULL) OR ("fee_currency" ~ '^[a-z]{3}$'::"text"))),
    CONSTRAINT "agreements_fee_only_for_clients" CHECK (
CASE "type"
    WHEN 'client'::"text" THEN ((("fee_amount_cents" IS NOT NULL) AND ("fee_currency" IS NOT NULL) AND ("fee_description" IS NOT NULL)) OR (("fee_amount_cents" IS NULL) AND ("fee_currency" IS NULL) AND ("fee_description" IS NULL)))
    ELSE (("fee_amount_cents" IS NULL) AND ("fee_currency" IS NULL) AND ("fee_description" IS NULL))
END),
    CONSTRAINT "agreements_filename_check" CHECK (("length"(TRIM(BOTH FROM "filename")) > 0)),
    CONSTRAINT "agreements_party_matches_type" CHECK (
CASE "type"
    WHEN 'client'::"text" THEN (("company_id" IS NOT NULL) AND ("deal_id" IS NOT NULL) AND ("team_member_id" IS NULL) AND ("vendor_id" IS NULL))
    WHEN 'employee'::"text" THEN (("team_member_id" IS NOT NULL) AND ("company_id" IS NULL) AND ("deal_id" IS NULL) AND ("vendor_id" IS NULL))
    WHEN 'contractor'::"text" THEN (("team_member_id" IS NOT NULL) AND ("company_id" IS NULL) AND ("deal_id" IS NULL) AND ("vendor_id" IS NULL))
    WHEN 'vendor'::"text" THEN (("vendor_id" IS NOT NULL) AND ("company_id" IS NULL) AND ("deal_id" IS NULL) AND ("team_member_id" IS NULL))
    ELSE NULL::boolean
END),
    CONSTRAINT "agreements_sha256_check" CHECK (("sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "agreements_signer_title_check" CHECK (("length"(TRIM(BOTH FROM "signer_title")) > 0)),
    CONSTRAINT "agreements_size_bytes_check" CHECK ((("size_bytes" IS NULL) OR ("size_bytes" > 0))),
    CONSTRAINT "agreements_storage_path_check" CHECK (("length"(TRIM(BOTH FROM "storage_path")) > 0)),
    CONSTRAINT "agreements_title_check" CHECK (("length"(TRIM(BOTH FROM "title")) > 0)),
    CONSTRAINT "agreements_type_check" CHECK (("type" = ANY (ARRAY['client'::"text", 'employee'::"text", 'contractor'::"text", 'vendor'::"text"])))
);


--
-- Name: TABLE "agreements"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."agreements" IS 'One row is: one agreement Edge8 and one other party sign electronically — a client''s contract on a deal, an employee''s or contractor''s contract, or a vendor''s. [transactional · Revenue documents | tier 3 support | active]';


--
-- Name: COLUMN "agreements"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."id" IS 'Primary key. For a client agreement it is also the id of its file''s program_documents row, and the subject_id of its two signature approvals.';


--
-- Name: COLUMN "agreements"."type"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."type" IS 'Who the other party is, which decides the link the row carries and where they sign. Valid values: [client, employee, contractor, vendor]';


--
-- Name: COLUMN "agreements"."title"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."title" IS 'What the agreement is called, as both parties see it in emails and on the signed copy.';


--
-- Name: COLUMN "agreements"."company_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."company_id" IS 'The client company (companies); set on client agreements only.';


--
-- Name: COLUMN "agreements"."deal_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."deal_id" IS 'The deal the agreement closes (deals); set on client agreements only.';


--
-- Name: COLUMN "agreements"."team_member_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."team_member_id" IS 'The employment or contract the agreement is for (team_members); set on employee and contractor agreements only.';


--
-- Name: COLUMN "agreements"."vendor_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."vendor_id" IS 'The vendor (vendors); set on vendor agreements only.';


--
-- Name: COLUMN "agreements"."signer_person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."signer_person_id" IS 'The person (people) who signs for the other party; only they can sign it.';


--
-- Name: COLUMN "agreements"."signer_title"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."signer_title" IS 'The signer''s title as the agreement names it, such as Director; they confirm or correct it when they sign.';


--
-- Name: COLUMN "agreements"."filename"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."filename" IS 'The uploaded file''s name.';


--
-- Name: COLUMN "agreements"."storage_path"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."storage_path" IS 'Where the file is in the private program-documents storage bucket.';


--
-- Name: COLUMN "agreements"."content_type"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."content_type" IS 'The file''s format, which decides how the signing page shows it. Valid values: [text/markdown, application/pdf]';


--
-- Name: COLUMN "agreements"."sha256"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."sha256" IS 'The sha256 of the stored file, in lowercase hex. Both signatures pin it, and it is checked again at each one, so nobody signs text that changed.';


--
-- Name: COLUMN "agreements"."size_bytes"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."size_bytes" IS 'The file''s size in bytes.';


--
-- Name: COLUMN "agreements"."fee_amount_cents"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."fee_amount_cents" IS 'The invoice raised in QuickBooks when the client signs, in the minor unit of fee_currency; client agreements only.';


--
-- Name: COLUMN "agreements"."fee_currency"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."fee_currency" IS 'The fee''s ISO 4217 currency code, lowercase; client agreements only.';


--
-- Name: COLUMN "agreements"."fee_description"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."fee_description" IS 'The invoice line''s description; client agreements only.';


--
-- Name: COLUMN "agreements"."prepared_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."prepared_by" IS 'The person (people) who uploaded and prepared the agreement.';


--
-- Name: COLUMN "agreements"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."created_at" IS 'When the agreement was prepared.';


--
-- Name: COLUMN "agreements"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."updated_at" IS 'When the row last changed.';


--
-- Name: COLUMN "agreements"."archived_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."archived_at" IS 'When the agreement was archived; its signatures and signed copy are kept.';


--
-- Name: COLUMN "agreements"."archived_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."agreements"."archived_by" IS 'The person (people) who archived it.';


--
-- Name: ai_calls; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."ai_calls" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "site" "text" NOT NULL,
    "class" "text" NOT NULL,
    "provider" "text" NOT NULL,
    "model" "text" NOT NULL,
    "input_tokens" integer,
    "output_tokens" integer,
    "cache_read_tokens" integer,
    "cache_write_tokens" integer,
    "cost_usd" numeric(12,6),
    "latency_ms" integer NOT NULL,
    "prompt_version" "text" NOT NULL,
    "input_hash" "text" NOT NULL,
    "run_id" "uuid",
    "ok" boolean NOT NULL,
    "error_kind" "text",
    CONSTRAINT "ai_calls_class_check" CHECK (("class" = ANY (ARRAY['S'::"text", 'C'::"text", 'B'::"text", 'A'::"text"]))),
    CONSTRAINT "ai_calls_error_kind_check" CHECK (("error_kind" = ANY (ARRAY['refusal'::"text", 'max_tokens'::"text", 'timeout'::"text", 'connection'::"text", 'rate_limit'::"text", 'api_error'::"text", 'unknown'::"text"]))),
    CONSTRAINT "ai_calls_provider_check" CHECK (("provider" = ANY (ARRAY['anthropic'::"text", 'openrouter'::"text", 'google'::"text"])))
);


--
-- Name: TABLE "ai_calls"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."ai_calls" IS 'One row is: one model call made through the kernel/ai gateway — its site, data class, provider, model, tokens, latency and outcome, never its prompt or completion. [other · Logs, audit & telemetry | tier 3 support | active]';


--
-- Name: COLUMN "ai_calls"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."id" IS 'Primary key.';


--
-- Name: COLUMN "ai_calls"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."created_at" IS 'When the call finished (row insert time).';


--
-- Name: COLUMN "ai_calls"."site"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."site" IS 'The call site name, the same string logAiUsage logs and modelFor keys its env override off (e.g. resume-screen, writer-letter-gather).';


--
-- Name: COLUMN "ai_calls"."class"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."class" IS 'The data class the call site declared at call time. Valid values: [S, C, B, A]. S sensitive (official Anthropic API only), C confidential, B internal output, A public output. The routing rule lives in kernel/ai/routing.ts, not here.';


--
-- Name: COLUMN "ai_calls"."provider"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."provider" IS 'The host that served the call. Valid values: [anthropic, openrouter, google]. anthropic is api.anthropic.com; google is the Gemini image API.';


--
-- Name: COLUMN "ai_calls"."model"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."model" IS 'The model id sent on the request, in the provider''s own spelling.';


--
-- Name: COLUMN "ai_calls"."input_tokens"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."input_tokens" IS 'Uncached input tokens from the response usage; null when the call failed before a response.';


--
-- Name: COLUMN "ai_calls"."output_tokens"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."output_tokens" IS 'Output tokens (thinking included) from the response usage; null when the call failed before a response.';


--
-- Name: COLUMN "ai_calls"."cache_read_tokens"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."cache_read_tokens" IS 'Prompt-cache read tokens from the response usage; null when the provider reports none.';


--
-- Name: COLUMN "ai_calls"."cache_write_tokens"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."cache_write_tokens" IS 'Prompt-cache write tokens from the response usage; null when the provider reports none.';


--
-- Name: COLUMN "ai_calls"."cost_usd"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."cost_usd" IS 'Cost in USD as the provider reported it (OpenRouter returns usage.cost); null until the versioned price table prices the tokens.';


--
-- Name: COLUMN "ai_calls"."latency_ms"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."latency_ms" IS 'Wall-clock milliseconds from request to response (or to the error), measured by the gateway.';


--
-- Name: COLUMN "ai_calls"."prompt_version"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."prompt_version" IS 'The call site''s prompt version constant, bumped when its prompt changes, so an eval can tell prompt changes from model changes.';


--
-- Name: COLUMN "ai_calls"."input_hash"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."input_hash" IS 'sha256 (hex) of the request''s messages; matches identical inputs without storing them.';


--
-- Name: COLUMN "ai_calls"."run_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."run_id" IS 'The routine_runs row the call ran under; null until the run handle (triggerRoutine) lands.';


--
-- Name: COLUMN "ai_calls"."ok"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."ok" IS 'True when the provider returned usable output; false on an error, a refusal or a max_tokens cut-off.';


--
-- Name: COLUMN "ai_calls"."error_kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."ai_calls"."error_kind" IS 'Why ok is false. Valid values: [refusal, max_tokens, timeout, connection, rate_limit, api_error, unknown]. Null when ok.';


--
-- Name: ai_programs; Type: TABLE; Schema: company_os; Owner: -
--

