    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "application_stages_stage_kind_check" CHECK (("stage_kind" = ANY (ARRAY['applied'::"text", 'screen'::"text", 'interview'::"text", 'assessment'::"text", 'reference'::"text", 'offer'::"text", 'hired'::"text", 'rejected'::"text"])))
);


--
-- Name: applications; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."applications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "candidate_id" "uuid",
    "job_requisition_id" "uuid" NOT NULL,
    "current_stage_id" "uuid",
    "source" "text" DEFAULT 'direct'::"text" NOT NULL,
    "source_detail" "text",
    "referrer_person_id" "uuid",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "rejection_reason" "text",
    "applied_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "decided_at" timestamp with time zone,
    "rating" integer,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resume_assessment" "text",
    "person_id" "uuid",
    "resume_document_id" "uuid",
    "cover_letter" "text",
    "answers" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "ai_summary" "jsonb",
    "ai_rating" numeric(3,1),
    "ai_screen_status" "text",
    "ai_screen_error" "text",
    "ai_screened_at" timestamp with time zone,
    "ai_model" "text",
    "archived_at" timestamp with time zone,
    "hr_assessment" "text",
    "chain_step" "text",
    "chain_started_at" timestamp with time zone,
    "chain_error" "text",
    "chain_proposal" "jsonb",
    "ai_screen_flags" "jsonb",
    CONSTRAINT "applications_ai_screen_flags_check" CHECK ((("ai_screen_flags" IS NULL) OR ("jsonb_typeof"("ai_screen_flags") = 'array'::"text"))),
    CONSTRAINT "applications_chain_proposal_check" CHECK ((("chain_proposal" IS NULL) OR ("jsonb_typeof"("chain_proposal") = 'object'::"text"))),
    CONSTRAINT "applications_chain_step_check" CHECK ((("chain_step" IS NULL) OR ("chain_step" = ANY (ARRAY['screen'::"text", 'triage'::"text", 'draft-invite'::"text", 'draft-decline'::"text", 'message-ready'::"text", 'send'::"text", 'interviewing'::"text", 'ask-decision'::"text", 'decision-ready'::"text", 'decide'::"text", 'closed'::"text"])))),
    CONSTRAINT "applications_rating_check" CHECK ((("rating" IS NULL) OR (("rating" >= 1) AND ("rating" <= 5)))),
    CONSTRAINT "applications_source_check" CHECK (("source" = ANY (ARRAY['direct'::"text", 'referral'::"text", 'job_board'::"text", 'linkedin'::"text", 'agency'::"text", 'sourced'::"text", 'career_site'::"text", 'event'::"text", 'recruiter'::"text", 'other'::"text"]))),
    CONSTRAINT "applications_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'on_hold'::"text", 'passive'::"text", 'withdrawn'::"text", 'rejected'::"text", 'hired'::"text", 'future_consideration'::"text"])))
);


--
-- Name: COLUMN "applications"."archived_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."applications"."archived_at" IS 'Soft-archive timestamp. NULL = active. Set by the admin ATS Delete action; reversible via Restore.';


--
-- Name: COLUMN "applications"."hr_assessment"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."applications"."hr_assessment" IS 'Recruiter-owned free-text assessment for this application. Overrides/augments the read-only AI screen; edited freely.';


--
-- Name: COLUMN "applications"."chain_step"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."applications"."chain_step" IS 'The step the hiring chain (Z.9) runs next for this application, or waits at; null when the application is not in a chain run. Valid values: [screen, triage, draft-invite, draft-decline, message-ready, send, interviewing, ask-decision, decision-ready, decide, closed].';


--
-- Name: COLUMN "applications"."chain_started_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."applications"."chain_started_at" IS 'When this application''s chain run started; part of every step''s tick, so a run started again reaches its first step anew.';


--
-- Name: COLUMN "applications"."chain_error"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."applications"."chain_error" IS 'Why the driver stopped the run after three failed attempts at one step; null while the run is healthy. Retry clears it.';


--
-- Name: COLUMN "applications"."chain_proposal"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."applications"."chain_proposal" IS 'A recruiter''s proposed decision waiting for the approver, as {outcome, reason, proposedBy}; outcome is hired or rejected. Null when no decision is proposed.';


--
-- Name: COLUMN "applications"."ai_screen_flags"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."applications"."ai_screen_flags" IS 'What the resume pre-check and the screening model found in the candidate''s own documents that reads as instructions to a reader or as hidden text, as an array of {source, kind, quote}; null before a screen. A flag holds the application for a person; it never advances or declines it.';


--
-- Name: approvals; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."approvals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "subject_type" "text" NOT NULL,
    "subject_id" "text" NOT NULL,
    "requested_by" "uuid",
    "approver_person_id" "uuid",
    "state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "decided_by" "uuid",
    "decided_at" timestamp with time zone,
    "reason" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "approver_permission" "text",
    CONSTRAINT "approvals_state_check" CHECK (("state" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "approvals_subject_id_check" CHECK (("btrim"("subject_id") <> ''::"text")),
    CONSTRAINT "approvals_subject_type_check" CHECK (("btrim"("subject_type") <> ''::"text"))
);


--
-- Name: TABLE "approvals"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."approvals" IS 'One row is: one request for somebody''s decision and its outcome — a leave request, a contractor estimate or submitted work, an assistant action — whatever flow raised it. [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "approvals"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."id" IS 'Primary key.';


--
-- Name: COLUMN "approvals"."subject_type"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."subject_type" IS 'What is being approved: a word from kernel/approvals/vocabulary.ts (time_off, contractor_estimate, contractor_work, assistant_action). Vocabulary in code, not a check constraint, so a new flow needs no migration.';


--
-- Name: COLUMN "approvals"."subject_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."subject_id" IS 'The thing being approved within its type: the leave row''s id, the work request''s id, the assistant''s tool-call id. Text, because not every subject is a row.';


--
-- Name: COLUMN "approvals"."requested_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."requested_by" IS 'The person who asked, referencing people.id, when the flow knows them.';


--
-- Name: COLUMN "approvals"."approver_person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."approver_person_id" IS 'The person who must decide, as the flow resolved it, referencing people.id. Null means any admin.';


--
-- Name: COLUMN "approvals"."state"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."state" IS 'Where the request stands. Valid values: [pending, approved, rejected, cancelled]';


--
-- Name: COLUMN "approvals"."decided_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."decided_by" IS 'The person who decided or withdrew it, referencing people.id, when known.';


--
-- Name: COLUMN "approvals"."decided_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."decided_at" IS 'When it was decided or withdrawn.';


--
-- Name: COLUMN "approvals"."reason"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."reason" IS 'The decider''s note, when the flow asks for one.';


--
-- Name: COLUMN "approvals"."metadata"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."metadata" IS 'The line the lists show (`label`) and any flow detail worth keeping with the decision.';


--
-- Name: COLUMN "approvals"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."created_at" IS 'When the request was raised.';


--
-- Name: COLUMN "approvals"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."updated_at" IS 'When the row last changed; maintained by a trigger.';


--
-- Name: COLUMN "approvals"."approver_permission"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."approvals"."approver_permission" IS 'The permission whose holders may decide ("reimbursements.check"), when the request waits on a role rather than a person; null for a request addressed to a person or to any admin.';


--
-- Name: assistant_conversations; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."assistant_conversations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "surface" "text" NOT NULL,
    "owner_auth_user_id" "uuid" NOT NULL,
    "owner_person_id" "uuid",
    "title" "text" DEFAULT 'New chat'::"text" NOT NULL,
    "messages" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "display_items" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "last_message_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "assistant_conversations_surface_check" CHECK (("surface" = ANY (ARRAY['admin'::"text", 'team'::"text"])))
);


--
-- Name: audit_log; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."audit_log" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "actor_person_id" "uuid",
    "actor_label" "text",
    "table_name" "text" NOT NULL,
    "record_id" "uuid",
    "operation" "text" NOT NULL,
    "old_data" "jsonb",
    "new_data" "jsonb",
    "context" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "changed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "audit_log_operation_check" CHECK (("operation" = ANY (ARRAY['insert'::"text", 'update'::"text", 'delete'::"text", 'archive'::"text", 'restore'::"text", 'bulk_update'::"text", 'bulk_archive'::"text", 'bulk_delete'::"text", 'read'::"text"])))
);


--
-- Name: automation_effects; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."automation_effects" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "key" "text" NOT NULL,
    "routine_id" "text" NOT NULL,
    "run_id" "uuid",
    "kind" "text" NOT NULL,
    "status" "text" NOT NULL,
    "attempt" integer DEFAULT 1 NOT NULL,
    "claimed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "done_at" timestamp with time zone,
    "provider_ref" "text",
    "detail" "jsonb",
    "summary" "text",
    CONSTRAINT "automation_effects_kind_check" CHECK (("kind" = ANY (ARRAY['lark'::"text", 'publish'::"text", 'webhook'::"text"]))),
    CONSTRAINT "automation_effects_shadow_key" CHECK ((("status" = 'shadow'::"text") = ("key" ~~ 'shadow:%'::"text"))),
    CONSTRAINT "automation_effects_shadow_says_what" CHECK ((("status" <> 'shadow'::"text") OR ("length"("btrim"(COALESCE("summary", ''::"text"))) > 0))),
    CONSTRAINT "automation_effects_status_check" CHECK (("status" = ANY (ARRAY['claimed'::"text", 'done'::"text", 'released'::"text", 'unknown'::"text", 'shadow'::"text"]))),
    CONSTRAINT "automation_effects_summary_length" CHECK ((("summary" IS NULL) OR ("length"("summary") <= 500)))
);


--
-- Name: TABLE "automation_effects"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."automation_effects" IS 'One row is: one external effect a routine claimed before acting, of a kind the provider cannot dedupe (a Lark post, a publish, an outbound webhook), and what became of it; or, from a run in shadow mode, one it would have made. [other · Logs, audit & telemetry | tier 3 support | active]';


--
-- Name: COLUMN "automation_effects"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."id" IS 'Primary key.';


--
-- Name: COLUMN "automation_effects"."key"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."key" IS 'The effect''s idempotency key, <entity>:<effect>:<subject>[:<period>]; unique, so an effect is claimed once. A shadow row''s key is shadow:<key>, so it never occupies the live key.';


--
-- Name: COLUMN "automation_effects"."routine_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."routine_id" IS 'The routine that claimed it (a routine_runs routine id).';


--
-- Name: COLUMN "automation_effects"."run_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."run_id" IS 'The run that last claimed it; null when that run row is gone.';


--
-- Name: COLUMN "automation_effects"."kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."kind" IS 'Valid values: [lark, publish, webhook]. Email and database effects keep their own claims (decision Y.82).';


--
-- Name: COLUMN "automation_effects"."status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."status" IS 'Valid values: [claimed, done, released, unknown, shadow]. claimed while the effect is under way; done with its provider reference; released when the code saw it fail (claimable again); unknown when its run ended without saying, for a person to decide; shadow when a run in shadow mode recorded it instead of acting (nothing was sent).';


--
-- Name: COLUMN "automation_effects"."attempt"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."attempt" IS 'How many times the key has been claimed; a released key claimed again counts up.';


--
-- Name: COLUMN "automation_effects"."claimed_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."claimed_at" IS 'When the latest claim was made.';


--
-- Name: COLUMN "automation_effects"."done_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."done_at" IS 'When it was marked done; null otherwise.';


--
-- Name: COLUMN "automation_effects"."provider_ref"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."provider_ref" IS 'The provider''s reference for the effect (a Lark message id, a published URL); null when the provider gives none.';


--
-- Name: COLUMN "automation_effects"."detail"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."detail" IS 'Small facts about the effect (a target, a count, a payload hash); never a message body or personal data.';


--
-- Name: COLUMN "automation_effects"."summary"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."automation_effects"."summary" IS 'One line, at most 500 characters, saying what the effect carried and where (e.g. Lark DM to the revenue approver: proposal ready to review); required on a shadow row, where it is the record of what would have been sent. Never a message body.';


--
-- Name: board_columns; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."board_columns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "board_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    "is_done" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "wip_limit" integer,
    "is_not_doing" boolean DEFAULT false NOT NULL,
    CONSTRAINT "board_columns_done_or_not_doing" CHECK ((NOT ("is_done" AND "is_not_doing"))),
    CONSTRAINT "board_columns_wip_limit_positive" CHECK ((("wip_limit" IS NULL) OR ("wip_limit" > 0)))
);


--
-- Name: COLUMN "board_columns"."wip_limit"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."board_columns"."wip_limit" IS 'Optional work-in-progress limit for this column, shown as information ("7 / 5", amber) and never enforced; null means no limit. Describes the column, never a person.';


--
-- Name: COLUMN "board_columns"."is_not_doing"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."board_columns"."is_not_doing" IS 'True for the Not Doing column: a card moved here is closed without being done (tasks.status = not_doing, completed_at empty). Never true together with is_done.';


--
-- Name: board_members; Type: TABLE; Schema: company_os; Owner: -
