    "person_id" "uuid",
    "kind" "text" NOT NULL,
    "stage_id" "uuid",
    "mode" "text" DEFAULT 'live'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "to_email" "text" NOT NULL,
    "subject" "text" NOT NULL,
    "body_md" "text" NOT NULL,
    "drafted_body_md" "text" NOT NULL,
    "version" "text" NOT NULL,
    "send_key" "text" NOT NULL,
    "provider_ref" "text",
    "run_tick" "text",
    "error" "text",
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "claimed_at" timestamp with time zone,
    "sent_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "candidate_messages_approved_says_when" CHECK ((("status" <> ALL (ARRAY['approved'::"text", 'sending'::"text", 'sent'::"text"])) OR ("approved_at" IS NOT NULL))),
    CONSTRAINT "candidate_messages_body_md_check" CHECK (("btrim"("body_md") <> ''::"text")),
    CONSTRAINT "candidate_messages_kind_check" CHECK (("kind" = ANY (ARRAY['invite'::"text", 'decline'::"text", 'decision_hire'::"text", 'decision_reject'::"text"]))),
    CONSTRAINT "candidate_messages_mode_check" CHECK (("mode" = ANY (ARRAY['shadow'::"text", 'live'::"text"]))),
    CONSTRAINT "candidate_messages_send_key_check" CHECK (("send_key" ~~ 'hiring:msg:%'::"text")),
    CONSTRAINT "candidate_messages_sent_says_when" CHECK ((("status" = 'sent'::"text") = ("sent_at" IS NOT NULL))),
    CONSTRAINT "candidate_messages_shadow_never_sends" CHECK ((("mode" = 'live'::"text") OR ("status" = ANY (ARRAY['pending'::"text", 'withdrawn'::"text"])))),
    CONSTRAINT "candidate_messages_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'sending'::"text", 'sent'::"text", 'withdrawn'::"text", 'failed'::"text"]))),
    CONSTRAINT "candidate_messages_subject_check" CHECK (("btrim"("subject") <> ''::"text")),
    CONSTRAINT "candidate_messages_to_email_check" CHECK (("btrim"("to_email") <> ''::"text"))
);


--
-- Name: TABLE "candidate_messages"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."candidate_messages" IS 'One row is: one email the hiring chain drafted for one candidate on one application — an interview invitation, a decline, or a hire or rejection decision — from draft through a person''s approval to send. [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "candidate_messages"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."id" IS 'Primary key.';


--
-- Name: COLUMN "candidate_messages"."application_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."application_id" IS 'The application the message is about.';


--
-- Name: COLUMN "candidate_messages"."person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."person_id" IS 'The candidate''s person row, when there is one.';


--
-- Name: COLUMN "candidate_messages"."kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."kind" IS 'Valid values: [invite, decline, decision_hire, decision_reject].';


--
-- Name: COLUMN "candidate_messages"."stage_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."stage_id" IS 'The interview stage an invitation is for; null for other kinds.';


--
-- Name: COLUMN "candidate_messages"."mode"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."mode" IS 'Valid values: [shadow, live]. shadow rows are what a run in shadow mode would have sent; they are never approved or sent.';


--
-- Name: COLUMN "candidate_messages"."status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."status" IS 'Valid values: [pending, approved, sending, sent, withdrawn, failed]. pending waits for the approver; approved may be sent; sending is claimed by a send step; sent went out; withdrawn was not sent (Don''t send, a closed requisition, an archived application); failed could not be sent for a reason retrying cannot fix.';


--
-- Name: COLUMN "candidate_messages"."to_email"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."to_email" IS 'The address the message goes to, read from the candidate''s person row when drafted.';


--
-- Name: COLUMN "candidate_messages"."subject"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."subject" IS 'The email subject.';


--
-- Name: COLUMN "candidate_messages"."body_md"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."body_md" IS 'The message body as it will be sent (Markdown), after any edit by the approver.';


--
-- Name: COLUMN "candidate_messages"."drafted_body_md"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."drafted_body_md" IS 'The body as the chain drafted it, kept beside what went out.';


--
-- Name: COLUMN "candidate_messages"."version"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."version" IS 'A hash of recipient, subject and body; the approval is for this version, and the send step refuses any other.';


--
-- Name: COLUMN "candidate_messages"."send_key"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."send_key" IS 'The effect''s idempotency key, hiring:msg:<application>:<kind>[:<stage>], also sent as Resend''s Idempotency-Key; one live message in flight per key.';


--
-- Name: COLUMN "candidate_messages"."provider_ref"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."provider_ref" IS 'Resend''s message id once sent; null otherwise.';


--
-- Name: COLUMN "candidate_messages"."run_tick"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."run_tick" IS 'The chain step''s tick that drafted the row.';


--
-- Name: COLUMN "candidate_messages"."error"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."error" IS 'Why the last send failed; null otherwise.';


--
-- Name: COLUMN "candidate_messages"."approved_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."approved_by" IS 'The person who approved it.';


--
-- Name: COLUMN "candidate_messages"."approved_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."approved_at" IS 'When it was approved.';


--
-- Name: COLUMN "candidate_messages"."claimed_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."claimed_at" IS 'When a send step claimed it.';


--
-- Name: COLUMN "candidate_messages"."sent_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."sent_at" IS 'When it was sent; set exactly when status is sent.';


--
-- Name: COLUMN "candidate_messages"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."created_at" IS 'Row insert time.';


--
-- Name: COLUMN "candidate_messages"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."candidate_messages"."updated_at" IS 'Last change.';


