--
-- Name: client_status_reports; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."client_status_reports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "week" "text" NOT NULL,
    "step" "text" DEFAULT 'gather'::"text" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "facts" "jsonb",
    "ai_draft" "jsonb",
    "body_html" "text",
    "version" "text",
    "edited_by" "uuid",
    "edited_at" timestamp with time zone,
    "error" "text",
    "released_at" timestamp with time zone,
    "released_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "client_status_reports_released_is_whole" CHECK (((("step" = 'released'::"text") = ("released_at" IS NOT NULL)) AND (("step" <> 'released'::"text") OR (("body_html" IS NOT NULL) AND ("version" IS NOT NULL))))),
    CONSTRAINT "client_status_reports_step_check" CHECK (("step" = ANY (ARRAY['gather'::"text", 'draft'::"text", 'check'::"text", 'ask'::"text", 'ready'::"text", 'release'::"text", 'released'::"text", 'rejected'::"text", 'superseded'::"text", 'stopped'::"text"]))),
    CONSTRAINT "client_status_reports_stopped_says_why" CHECK ((("step" <> 'stopped'::"text") OR ("length"("btrim"(COALESCE("error", ''::"text"))) > 0))),
    CONSTRAINT "client_status_reports_week_check" CHECK (("week" ~ '^[0-9]{4}-W[0-9]{2}$'::"text"))
);


--
-- Name: TABLE "client_status_reports"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."client_status_reports" IS 'One row is: one client company''s weekly status report for one ISO week — the facts it was drafted from, the page the client would see, where its run is, and whether a person released it to the client''s portal. [transactional · Client delivery & work | tier 3 support | active]';


--
-- Name: COLUMN "client_status_reports"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."id" IS 'Primary key.';


--
-- Name: COLUMN "client_status_reports"."company_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."company_id" IS 'The client company the report is for.';


--
-- Name: COLUMN "client_status_reports"."week"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."week" IS 'The ISO week the report covers, in Saigon time, as YYYY-Www (2026-W41); unique with company_id, so one report per client per week.';


--
-- Name: COLUMN "client_status_reports"."step"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."step" IS 'Where the weekly run is (ADR 0015). gather, draft, check, ask and release are advanced by the tick driver; ready waits on a person''s decision; released is shown in the client''s portal; rejected and superseded are never shown; stopped carries its error until a person drafts again or uses the plain report. Valid values: [gather, draft, check, ask, ready, release, released, rejected, superseded, stopped]';


--
-- Name: COLUMN "client_status_reports"."started_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."started_at" IS 'The run''s epoch, part of every step''s tick key; reset when a person drafts again, so a fresh run gets fresh ticks.';


--
-- Name: COLUMN "client_status_reports"."facts"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."facts" IS 'The client-safe facts the draft is written from (card titles, lanes, done dates, roadmap status and client priority), parsed through an allowlist; never a token, hour or money figure, an assignee or a description.';


--
-- Name: COLUMN "client_status_reports"."ai_draft"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."ai_draft" IS 'The model''s structured output exactly as returned, kept so an approver''s edit can be learned from; null for a plain report or before the draft step.';


--
-- Name: COLUMN "client_status_reports"."body_html"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."body_html" IS 'The page the client would see once released, rendered from a fixed template; an approver''s edit replaces only its narrative sections.';


--
-- Name: COLUMN "client_status_reports"."version"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."version" IS 'The content hash of company, week, title and body_html that the open approval names; the release goes ahead only when the approved version equals it.';


--
-- Name: COLUMN "client_status_reports"."edited_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."edited_by" IS 'The person who last edited the narrative before release; null when nobody did.';


--
-- Name: COLUMN "client_status_reports"."edited_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."edited_at" IS 'When the narrative was last edited; null when nobody did.';


--
-- Name: COLUMN "client_status_reports"."error"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."error" IS 'Why the run stopped (the failed check rule or the last step''s error); required when step is stopped, cleared when a person drafts again.';


--
-- Name: COLUMN "client_status_reports"."released_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."released_at" IS 'When the page was released to the client''s portal; set exactly when step is released.';


--
-- Name: COLUMN "client_status_reports"."released_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."released_by" IS 'The person whose approval released the page.';


--
-- Name: COLUMN "client_status_reports"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."created_at" IS 'When the opener inserted the row.';


--
-- Name: COLUMN "client_status_reports"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."client_status_reports"."updated_at" IS 'When the row last changed, stamped by the writer.';


