COMMENT ON COLUMN "company_os"."coaching_commitment_history"."id" IS 'Synthetic primary key.';


--
-- Name: COLUMN "coaching_commitment_history"."commitment_id"; Type: COMMENT; Schema: company_os; Owner: -
