    "one_on_one_id" "uuid",
    "title" "text" NOT NULL,
    "owner" "text" DEFAULT 'member'::"text" NOT NULL,
    "due_on" "date",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "status_note" "text",
    "status_updated_by" "uuid",
    "status_updated_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_by" "uuid",
    "ask_now_sent_at" timestamp with time zone,
    "card_done_at" timestamp with time zone,
    "plan_md" "text",
    CONSTRAINT "coaching_commitments_owner_check" CHECK (("owner" = ANY (ARRAY['coach'::"text", 'member'::"text"]))),
    CONSTRAINT "coaching_commitments_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'on_track'::"text", 'needs_attention'::"text", 'completed'::"text", 'dropped'::"text", 'blocked'::"text"])))
);


--
-- Name: COLUMN "coaching_commitments"."ask_now_sent_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_commitments"."ask_now_sent_at" IS 'When the member last used "Ask now" on this blocked commitment to reach their coach; null until they ever have. One send per card per Saigon day is enforced against it (K.22).';


--
-- Name: COLUMN "coaching_commitments"."card_done_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_commitments"."card_done_at" IS 'When a board card linked to this commitment reached a done column, as a SUGGESTION to its owner that the commitment was kept. Never a status: only the owner moves a commitment to completed. Null until a linked card is finished, and cleared again when they dismiss the suggestion.';


--
-- Name: COLUMN "coaching_commitments"."plan_md"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_commitments"."plan_md" IS 'The owner''s own sentence about WHEN they will do this, in their words — an implementation intention, not a deadline. Never read by a cron, a digest or any overdue calculation; the due date is the only date this product acts on.';


--
-- Name: coaching_context; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."coaching_context" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "coach_id" "uuid",
    "kind" "text" NOT NULL,
    "title" "text" NOT NULL,
    "markdown" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "coaching_context_kind_check" CHECK (("kind" = ANY (ARRAY['foundation'::"text", 'company'::"text", 'okrs'::"text"])))
);


--
-- Name: coaching_goal_comments; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."coaching_goal_comments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "goal_id" "uuid" NOT NULL,
    "author_team_member_id" "uuid" NOT NULL,
    "body" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "coaching_goal_comments_body_check" CHECK ((("char_length"("body") >= 1) AND ("char_length"("body") <= 2000)))
);


--
-- Name: coaching_member_notes; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."coaching_member_notes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "coaching_profile_id" "uuid" NOT NULL,
    "body" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone
);


--
-- Name: TABLE "coaching_member_notes"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."coaching_member_notes" IS 'One note the member wrote for themselves between 1-1s — a win, a moment, something worth remembering.';


--
-- Name: COLUMN "coaching_member_notes"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_member_notes"."id" IS 'Synthetic primary key.';


--
-- Name: COLUMN "coaching_member_notes"."coaching_profile_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_member_notes"."coaching_profile_id" IS 'The coaching profile whose member wrote this note; cascades on delete.';


--
-- Name: COLUMN "coaching_member_notes"."body"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_member_notes"."body" IS 'What the member wrote, verbatim, one to a thousand characters.';


--
-- Name: COLUMN "coaching_member_notes"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_member_notes"."created_at" IS 'When the note was written, which is what orders the list and decides whether it is newer than the last 1-1.';


--
-- Name: COLUMN "coaching_member_notes"."archived_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_member_notes"."archived_at" IS 'When the member tidied the note away; null while it is live. Archived rather than deleted so the brag document keeps what it already quoted.';


--
-- Name: coaching_noticed; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."coaching_noticed" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "coaching_profile_id" "uuid" NOT NULL,
    "written_by" "uuid" NOT NULL,
    "value_id" "uuid",
    "body" "text" NOT NULL,
    "subject" "text",
    "noticed_on" "date" DEFAULT (("now"() AT TIME ZONE 'Asia/Ho_Chi_Minh'::"text"))::"date" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone
);


--
-- Name: TABLE "coaching_noticed"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."coaching_noticed" IS 'One sentence about a specific piece of work, tied to a company value. Visible ONLY to the person it is about and the person who wrote it. It is never counted, never aggregated, never compared between people and never near a review rating — if this table ever needs a "top recognised" query, the feature was built wrong.';


--
-- Name: COLUMN "coaching_noticed"."value_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_noticed"."value_id" IS 'The company value the behaviour showed, read from org. Nullable so a value retired later does not delete the sentence.';


--
-- Name: COLUMN "coaching_noticed"."body"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_noticed"."body" IS 'The sentence, in the writer''s own words. Names a behaviour and a piece of work, not a trait.';


--
-- Name: COLUMN "coaching_noticed"."subject"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_noticed"."subject" IS 'What the work was, so the sentence has something to point at.';


--
-- Name: coaching_ocean_profiles; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."coaching_ocean_profiles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "coaching_profile_id" "uuid" NOT NULL,
    "openness_rating" "text",
    "openness_evidence" "text",
    "conscientiousness_rating" "text",
    "conscientiousness_evidence" "text",
    "extraversion_rating" "text",
    "extraversion_evidence" "text",
    "agreeableness_rating" "text",
    "agreeableness_evidence" "text",
    "neuroticism_rating" "text",
    "neuroticism_evidence" "text",
    "snapshot_markdown" "text",
    "guidance_markdown" "text",
    "published" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: coaching_one_on_ones; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."coaching_one_on_ones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "coaching_profile_id" "uuid" NOT NULL,
    "held_on" "date" NOT NULL,
    "status" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "prep_markdown" "text",
    "prep_generated_at" timestamp with time zone,
    "summary_markdown" "text",
    "shared_summary_markdown" "text",
    "shared_published_at" timestamp with time zone,
    "ai_model" "text",
    "ai_error" "text",
    "archived_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "mode_coach_pct" integer,
    "mode_mentor_pct" integer,
    "mode_direct_pct" integer,
    "minutes_token" "text",
    "transcript_source" "text",
    "meeting_id" "uuid",
    "prep_shared_markdown" "text",
    "skip_reason" "text",
    "transcript_sha256" "text",
    "starts_at" time without time zone,
    "moved_from" "date",
    "move_reason" "text",
    "prep_member_edits" "jsonb",
    "coach_voltage_md" "text",
    "held_source" "text",
    "lark_hold_id" "text",
    "lark_hold_synced_at" timestamp with time zone,
    "lark_hold_error" "text",
    "marked_held_on" "date",
    "format" "text",
    "led_by" "uuid",
    "kind" "text" DEFAULT 'one_on_one'::"text" NOT NULL,
    CONSTRAINT "coaching_one_on_ones_format_check" CHECK ((("format" IS NULL) OR ("format" = ANY (ARRAY['video'::"text", 'call'::"text", 'in_person'::"text", 'chat'::"text"])))),
    CONSTRAINT "coaching_one_on_ones_held_source_check" CHECK ((("held_source" IS NULL) OR ("held_source" = ANY (ARRAY['meeting'::"text", 'written'::"text"])))),
    CONSTRAINT "coaching_one_on_ones_kind_check" CHECK (("kind" = ANY (ARRAY['one_on_one'::"text", 'goals_check'::"text"]))),
    CONSTRAINT "coaching_one_on_ones_mode_split" CHECK (((("mode_coach_pct" IS NULL) = ("mode_mentor_pct" IS NULL)) AND (("mode_mentor_pct" IS NULL) = ("mode_direct_pct" IS NULL)) AND (("mode_coach_pct" IS NULL) OR ((("mode_coach_pct" >= 0) AND ("mode_coach_pct" <= 100)) AND (("mode_mentor_pct" >= 0) AND ("mode_mentor_pct" <= 100)) AND (("mode_direct_pct" >= 0) AND ("mode_direct_pct" <= 100)) AND ((("mode_coach_pct" + "mode_mentor_pct") + "mode_direct_pct") = 100))))),
    CONSTRAINT "coaching_one_on_ones_status_check" CHECK (("status" = ANY (ARRAY['scheduled'::"text", 'held'::"text", 'skipped'::"text"]))),
    CONSTRAINT "coaching_one_on_ones_transcript_source_check" CHECK (("transcript_source" = ANY (ARRAY['minutes_auto'::"text", 'minutes_link'::"text", 'manual'::"text"])))
);


--
-- Name: COLUMN "coaching_one_on_ones"."starts_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."starts_at" IS 'The Saigon wall-clock start time of this 1-1, set from the profile preference when the row is scheduled; null when the meeting has a date but no time.';


--
-- Name: COLUMN "coaching_one_on_ones"."moved_from"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."moved_from" IS 'The date this 1-1 sat on before its last move; null on a 1-1 that was never moved. Overwritten by each move, so it is the previous date, not the original one (K.33).';


--
-- Name: COLUMN "coaching_one_on_ones"."move_reason"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."move_reason" IS 'The one line the coach wrote for why this 1-1 moved; null on a 1-1 that was never moved (K.33).';


--
-- Name: COLUMN "coaching_one_on_ones"."prep_member_edits"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."prep_member_edits" IS 'The member''s amendments to the shared prep, {"struck": [bullet text], "added": [line]}; null when they changed nothing. The coach''s prep_shared_markdown is never rewritten by it.';


--
-- Name: COLUMN "coaching_one_on_ones"."coach_voltage_md"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."coach_voltage_md" IS 'The coach''s one-line private note on their own energy before this 1-1; coach-tier only, never selected for the member, cleared when the meeting is marked held.';


--
-- Name: COLUMN "coaching_one_on_ones"."held_source"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."held_source" IS 'How a held 1-1 was held: meeting (the default, null on older rows) or written, when the pre-meeting answers plus the coach reply counted as the 1-1 (K.35).';


--
-- Name: COLUMN "coaching_one_on_ones"."lark_hold_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."lark_hold_id" IS 'The Lark calendar event this 1-1 is held by, created and owned by the app (ADR 0009). Null means no hold: Lark is unconfigured, or the 1-1 is not in a state that deserves one.';


--
-- Name: COLUMN "coaching_one_on_ones"."lark_hold_synced_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."lark_hold_synced_at" IS 'When the hold was last made to agree with this row. Stale with no error means the reconciler has not reached it yet.';


--
-- Name: COLUMN "coaching_one_on_ones"."lark_hold_error"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."lark_hold_error" IS 'Why the last attempt to make the hold agree failed, for a human reading the row. Cleared on the next success.';


--
-- Name: COLUMN "coaching_one_on_ones"."marked_held_on"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."marked_held_on" IS 'The business date the coach marked this 1-1 held by answering that it happened; null while it is not held, when a recording or the written exchange marked it held (those prove the day), and on 1-1s marked held before 27 Sep 2026. Held late is marked_held_on after held_on, written by the coach''s answer, never by a routine (A.31, ADR-0010).';


--
-- Name: COLUMN "coaching_one_on_ones"."format"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."format" IS 'How the session happened, as the coach recorded it when marking it done: video, call, in_person or chat. Null when not said (every row before K.80). Optional; never required to close a session.';


--
-- Name: COLUMN "coaching_one_on_ones"."led_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."led_by" IS 'The team member who led this session when it was not the profile''s coach (a dotted-line or skip-level leader); null means the coach led it.';


--
-- Name: COLUMN "coaching_one_on_ones"."kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_one_on_ones"."kind" IS 'What kind of session this was. Valid values: [one_on_one, goals_check]. A goals_check is a short session on the member''s goals and does not count toward the 1-1 rhythm.';


--
-- Name: coaching_priorities; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."coaching_priorities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "coaching_profile_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "detail_markdown" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "objective_id" "uuid",
    "key_result_id" "uuid",
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "link_url" "text",
    "link_title" "text",
    CONSTRAINT "coaching_priorities_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'retired'::"text"])))
);


--
-- Name: COLUMN "coaching_priorities"."link_url"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_priorities"."link_url" IS 'One optional thing to read or do about this growth priority, as a full URL. Deliberately a free URL and not a library reference: coaching is a portable entity and may not depend on the internal library.';


--
-- Name: COLUMN "coaching_priorities"."link_title"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_priorities"."link_title" IS 'What to call the link on screen, so the member reads a title rather than a URL. Null when link_url is null.';


--
-- Name: coaching_profiles; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."coaching_profiles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "team_member_id" "uuid" NOT NULL,
    "coach_id" "uuid",
    "okrs_markdown" "text",
    "private_profile_markdown" "text",
    "cadence_days" integer DEFAULT 14 NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "retention_root" "text",
    "one_on_ones_paused_at" timestamp with time zone,
    "recap_language" "text",
    "preferred_time" time without time zone,
    "proposed_one_on_one_on" "date",
    "proposed_by" "text",
    "how_best_hours_md" "text",
    "how_feedback_md" "text",
    "how_quiet_md" "text",
    "how_curious_md" "text",
    CONSTRAINT "coaching_profiles_cadence_days_check" CHECK ((("cadence_days" >= 7) AND ("cadence_days" <= 90))),
    CONSTRAINT "coaching_profiles_proposed_by_check" CHECK ((("proposed_by" IS NULL) OR ("proposed_by" = ANY (ARRAY['member'::"text", 'coach'::"text"])))),
    CONSTRAINT "coaching_profiles_recap_language_check" CHECK ((("recap_language" IS NULL) OR ("recap_language" = ANY (ARRAY['vi'::"text", 'en'::"text"])))),
    CONSTRAINT "coaching_profiles_retention_root_check" CHECK (("retention_root" = ANY (ARRAY['belonging'::"text", 'links'::"text", 'sacrifice'::"text", 'watching'::"text"])))
);


--
-- Name: COLUMN "coaching_profiles"."one_on_ones_paused_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_profiles"."one_on_ones_paused_at" IS 'When the coach paused the 1-1 rhythm; null means the daily cycle keeps rolling next_one_on_one_on forward by cadence_days and prepping each one.';


--
-- Name: COLUMN "coaching_profiles"."preferred_time"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_profiles"."preferred_time" IS 'The Saigon wall-clock time the member prefers for 1-1s; copied onto each scheduled row as starts_at. Null means no preference.';


--
-- Name: COLUMN "coaching_profiles"."proposed_one_on_one_on"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_profiles"."proposed_one_on_one_on" IS 'A date proposed for the next 1-1 and not yet confirmed; cleared when the coach confirms it onto next_one_on_one_on or declines it. Null means there is no open proposal.';


--
-- Name: COLUMN "coaching_profiles"."proposed_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_profiles"."proposed_by" IS 'Who proposed proposed_one_on_one_on: member or coach. Null when there is no open proposal.';


--
-- Name: COLUMN "coaching_profiles"."how_best_hours_md"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_profiles"."how_best_hours_md" IS 'Written BY THE MEMBER: when they do their best work. The rare coaching row the member owns — their coach reads it, never writes it (L.3).';


--
-- Name: COLUMN "coaching_profiles"."how_feedback_md"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_profiles"."how_feedback_md" IS 'Written BY THE MEMBER: the kind of feedback they can actually use (L.3).';


--
-- Name: COLUMN "coaching_profiles"."how_quiet_md"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_profiles"."how_quiet_md" IS 'Written BY THE MEMBER: what it means when they go quiet (L.3).';


--
-- Name: COLUMN "coaching_profiles"."how_curious_md"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."coaching_profiles"."how_curious_md" IS 'Written BY THE MEMBER: what they are curious about right now (L.3).';


--
-- Name: coaching_talking_points; Type: TABLE; Schema: company_os; Owner: -
