--
-- Name: compensation_sensitive; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."compensation_sensitive" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "team_member_id" "uuid" NOT NULL,
