--

CREATE TABLE "company_os"."leave_policies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "auto_approve" boolean DEFAULT false NOT NULL,
    "year_basis" "text" DEFAULT 'calendar'::"text" NOT NULL,
    "accrual_cadence" "text" DEFAULT 'none'::"text" NOT NULL,
    "tiers" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "hours_per_day" numeric DEFAULT 8 NOT NULL,
    "min_increment_hours" numeric DEFAULT 4 NOT NULL,
    "carry_cap_hours" numeric,
    "bank_leave_types" "text"[] DEFAULT '{vacation}'::"text"[] NOT NULL,
    "honour_imported_balance" boolean DEFAULT false NOT NULL,
    "policy_text" "text",
    "counts_from" "text" DEFAULT 'probation_end'::"text" NOT NULL,
    CONSTRAINT "leave_policies_accrual_cadence_check" CHECK (("accrual_cadence" = ANY (ARRAY['none'::"text", 'monthly'::"text", 'semi_monthly'::"text"]))),
    CONSTRAINT "leave_policies_counts_from_check" CHECK (("counts_from" = ANY (ARRAY['probation_end'::"text", 'start_date'::"text"]))),
    CONSTRAINT "leave_policies_year_basis_check" CHECK (("year_basis" = ANY (ARRAY['calendar'::"text", 'anniversary'::"text"])))
);


--
-- Name: COLUMN "leave_policies"."year_basis"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."leave_policies"."year_basis" IS 'How the leave year is counted: calendar (resets 1 January) or anniversary (resets on the anniversary of the day probation ended). Valid values: [calendar, anniversary]';


--
-- Name: COLUMN "leave_policies"."accrual_cadence"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."leave_policies"."accrual_cadence" IS 'How often hours post to the bank: none (no paid leave), monthly (last day of the month) or semi_monthly (15th and last day). Valid values: [none, monthly, semi_monthly]';


--
-- Name: COLUMN "leave_policies"."tiers"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."leave_policies"."tiers" IS 'Entitlement by service year as a JSON array of {fromYear, hoursPerYear}, ascending; the tier in force is the last whose fromYear is at or below the current service year.';


--
-- Name: COLUMN "leave_policies"."hours_per_day"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."leave_policies"."hours_per_day" IS 'Length of one working day in hours; converts between the hours the bank is kept in and the days a page shows.';


--
-- Name: COLUMN "leave_policies"."min_increment_hours"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."leave_policies"."min_increment_hours" IS 'Smallest unit of leave a request may take, in hours (1 for hourly policies, 4 for half days).';


--
-- Name: COLUMN "leave_policies"."carry_cap_hours"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."leave_policies"."carry_cap_hours" IS 'Most hours that survive the year-end check; null carries everything, 0 carries nothing.';


--
-- Name: COLUMN "leave_policies"."bank_leave_types"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."leave_policies"."bank_leave_types" IS 'Which time_off leave types deduct from this bank (for instance vacation only, or vacation plus sick and personal).';


--
-- Name: COLUMN "leave_policies"."honour_imported_balance"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."leave_policies"."honour_imported_balance" IS 'When true the balance walk starts from the Day Off opening balance recorded in leave_adjustments on 6 July 2026 instead of from the anniversary date; set for policies whose Day Off figures were reconciled with the client.';


--
-- Name: COLUMN "leave_policies"."policy_text"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."leave_policies"."policy_text" IS 'The policy as people read it, shown on the admin, team and client portal time-off pages. Plain text; blank lines separate paragraphs.';


--
-- Name: COLUMN "leave_policies"."counts_from"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."leave_policies"."counts_from" IS 'The day accrual and the leave year count from: probation_end (the first contract) or start_date. Valid values: [probation_end, start_date]';


