);


--
-- Name: TABLE "ddl_log"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."ddl_log" IS 'One row is: one object changed by a schema change that reached production, with the migration that declared it. Written by the edge8_ddl_guard event triggers. [log · Platform | tier 3 support | active]';


--
-- Name: ddl_log_id_seq; Type: SEQUENCE; Schema: company_os; Owner: -
--

ALTER TABLE "company_os"."ddl_log" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "company_os"."ddl_log_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: ddl_proof_abort; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."ddl_proof_abort" (
    "id" bigint NOT NULL,
    "object_identity" "text"
);


--
-- Name: TABLE "ddl_proof_abort"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."ddl_proof_abort" IS 'Always empty. A proof transaction (edge8.proof = on) that ran DDL inserts here, and a deferred constraint trigger raises at commit, so such a transaction can only roll back. [log · Platform | tier 3 support | active]';


--
-- Name: ddl_proof_abort_id_seq; Type: SEQUENCE; Schema: company_os; Owner: -
--

ALTER TABLE "company_os"."ddl_proof_abort" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "company_os"."ddl_proof_abort_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


