--
-- Name: TABLE "deal_stage_log"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."deal_stage_log" IS 'One logged stage move of one deal.';


--
-- Name: COLUMN "deal_stage_log"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deal_stage_log"."id" IS 'Primary key.';


--
-- Name: COLUMN "deal_stage_log"."deal_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deal_stage_log"."deal_id" IS 'FK to deals; the deal that moved.';


--
-- Name: COLUMN "deal_stage_log"."from_stage_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deal_stage_log"."from_stage_id" IS 'FK to pipeline_stages; the stage the deal left (null when the deal was created into to_stage_id).';


--
-- Name: COLUMN "deal_stage_log"."to_stage_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deal_stage_log"."to_stage_id" IS 'FK to pipeline_stages; the stage the deal entered.';


--
-- Name: COLUMN "deal_stage_log"."kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deal_stage_log"."kind" IS 'What produced the row. Valid values: [move, create, seed]';


--
-- Name: COLUMN "deal_stage_log"."moved_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deal_stage_log"."moved_at" IS 'When the deal entered to_stage_id; aging in stage is measured from the latest row per deal.';


--
-- Name: COLUMN "deal_stage_log"."moved_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deal_stage_log"."moved_by" IS 'Audit label of the admin or routine that moved the deal; never used for a metric.';


--
-- Name: COLUMN "deal_stage_log"."note"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deal_stage_log"."note" IS 'Free-text note on the move, e.g. the seed marker or the bulk edit that produced it.';


--
-- Name: deal_stage_current; Type: VIEW; Schema: company_os; Owner: -
--

CREATE VIEW "company_os"."deal_stage_current" AS
 SELECT DISTINCT ON ("deal_stage_log"."deal_id") "deal_stage_log"."deal_id",
    "deal_stage_log"."to_stage_id",
    "deal_stage_log"."moved_at"
   FROM "company_os"."deal_stage_log"
  ORDER BY "deal_stage_log"."deal_id", "deal_stage_log"."moved_at" DESC;


--
-- Name: VIEW "deal_stage_current"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON VIEW "company_os"."deal_stage_current" IS 'The latest deal_stage_log row per deal: when the deal entered the stage it is in now.';


--
-- Name: deals; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."deals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "pipeline_id" "uuid" NOT NULL,
    "stage_id" "uuid",
    "title" "text" NOT NULL,
    "person_id" "uuid",
    "company_id" "uuid",
    "amount_cents" bigint DEFAULT 0 NOT NULL,
    "currency" "text" DEFAULT 'usd'::"text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "probability" integer,
    "owner_id" "uuid",
    "affiliate_id" "uuid",
    "source" "text",
    "expected_close_date" "date",
    "closed_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "service_line_id" "uuid",
    "next_step" "text",
    "next_step_date" "date",
    "handoff_status" "text" DEFAULT 'none'::"text" NOT NULL,
    "handoff_rejected_reason" "text",
    "handoff_note" "text",
    "handoff_decided_at" timestamp with time zone,
    "lost_reason" "text",
    "archived_at" timestamp with time zone,
    "archived_by" "text",
    "amount_usd_cents" bigint,
    "fx_rate" numeric,
    "fx_rate_fetched_at" timestamp with time zone,
    "proposal_url" "text",
    "contract_url" "text",
    "referrer_id" "uuid",
    "position" integer DEFAULT 0 NOT NULL,
    "referrer_company_id" "uuid",
    "campaign_id" "uuid",
    "stage_moved_by" "text",
    "stage_move_note" "text",
    CONSTRAINT "deals_check" CHECK ((("person_id" IS NOT NULL) OR ("company_id" IS NOT NULL))),
    CONSTRAINT "deals_handoff_rejected_reason_check" CHECK (("handoff_rejected_reason" = ANY (ARRAY['not_qualified'::"text", 'bad_fit'::"text", 'duplicate'::"text", 'bad_timing'::"text", 'other'::"text"]))),
    CONSTRAINT "deals_handoff_status_check" CHECK (("handoff_status" = ANY (ARRAY['none'::"text", 'pending'::"text", 'accepted'::"text", 'rejected'::"text"]))),
    CONSTRAINT "deals_lost_reason_check" CHECK (("lost_reason" = ANY (ARRAY['price'::"text", 'competitor'::"text", 'no_decision'::"text", 'bad_fit'::"text", 'bad_timing'::"text", 'ghosted'::"text", 'other'::"text"]))),
    CONSTRAINT "deals_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'won'::"text", 'lost'::"text"])))
);


--
-- Name: COLUMN "deals"."proposal_url"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deals"."proposal_url" IS 'Link to the deal proposal document (free-form URL).';


--
-- Name: COLUMN "deals"."contract_url"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deals"."contract_url" IS 'Link to the deal contract document (free-form URL).';


--
-- Name: COLUMN "deals"."referrer_company_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deals"."referrer_company_id" IS 'Company that directly referred this deal (mirrors person referrer_id). Attributes referred deals to a company affiliate.';


--
-- Name: COLUMN "deals"."campaign_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deals"."campaign_id" IS 'FK to marketing_campaigns; the campaign this deal is attributed to, set by hand on the deal form until intake carries it.';


--
-- Name: COLUMN "deals"."stage_moved_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deals"."stage_moved_by" IS 'Who is moving the deal to a new stage, set in the same statement as stage_id and copied to deal_stage_log.moved_by by a trigger, then cleared; null means the writer did not say (A.32, ADR-0011).';


--
-- Name: COLUMN "deals"."stage_move_note"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."deals"."stage_move_note" IS 'Why the deal is moving, set with stage_id and copied to deal_stage_log.note by a trigger, then cleared (A.32, ADR-0011).';


--
-- Name: documents; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."documents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text",
    "storage_path" "text" NOT NULL,
    "mime_type" "text",
    "byte_size" bigint,
    "uploaded_by" "uuid",
    "entity_type" "text",
    "entity_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: email_agent_skills; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."email_agent_skills" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "agent_id" "uuid" NOT NULL,
    "version" integer NOT NULL,
    "body_md" "text" NOT NULL,
    "note" "text",
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "email_agent_skills_version_check" CHECK (("version" >= 1))
);


--
-- Name: TABLE "email_agent_skills"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."email_agent_skills" IS 'One row is: one version of one personal email agent''s brief (the skill), so every message records which version wrote it.';


--
-- Name: COLUMN "email_agent_skills"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agent_skills"."id" IS 'Primary key.';


--
-- Name: COLUMN "email_agent_skills"."agent_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agent_skills"."agent_id" IS 'FK to email_agents.';


--
-- Name: COLUMN "email_agent_skills"."version"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agent_skills"."version" IS '1, 2, 3; unique per agent. The agent runs its latest.';


--
-- Name: COLUMN "email_agent_skills"."body_md"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agent_skills"."body_md" IS 'The skill as Markdown: goal, voice, structure, rules, example emails.';


--
-- Name: COLUMN "email_agent_skills"."note"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agent_skills"."note" IS 'One line on what changed and why.';


--
-- Name: COLUMN "email_agent_skills"."created_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agent_skills"."created_by" IS 'Email of the admin who wrote it.';


--
-- Name: COLUMN "email_agent_skills"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agent_skills"."created_at" IS 'Row creation time.';


--
-- Name: email_agents; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."email_agents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "brand_id" "uuid",
    "audience_id" "uuid" NOT NULL,
    "from_email" "text",
    "reply_to" "text",
    "sources" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "cadence_days" integer DEFAULT 14 NOT NULL,
    "send_hour" smallint DEFAULT 8 NOT NULL,
    "review_mode" "text" DEFAULT 'sample'::"text" NOT NULL,
    "sample_size" integer DEFAULT 5 NOT NULL,
    "max_words" integer DEFAULT 150 NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "email_agents_cadence_days_check" CHECK ((("cadence_days" >= 1) AND ("cadence_days" <= 365))),
    CONSTRAINT "email_agents_max_words_check" CHECK ((("max_words" >= 20) AND ("max_words" <= 2000))),
    CONSTRAINT "email_agents_review_mode_check" CHECK (("review_mode" = ANY (ARRAY['hold_all'::"text", 'sample'::"text"]))),
    CONSTRAINT "email_agents_sample_size_check" CHECK ((("sample_size" >= 1) AND ("sample_size" <= 100))),
    CONSTRAINT "email_agents_send_hour_check" CHECK ((("send_hour" >= 0) AND ("send_hour" <= 23)))
);


--
-- Name: TABLE "email_agents"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."email_agents" IS 'One row is: one personal email agent, the context it may read, its rhythm and the audience it writes to.';


--
-- Name: COLUMN "email_agents"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."id" IS 'Primary key.';


--
-- Name: COLUMN "email_agents"."name"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."name" IS 'What the agent is called, for example "AIO student check-in".';


--
-- Name: COLUMN "email_agents"."brand_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."brand_id" IS 'FK to brands; the identity it sends as.';


--
-- Name: COLUMN "email_agents"."audience_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."audience_id" IS 'FK to email_audiences; who it writes to.';


--
-- Name: COLUMN "email_agents"."from_email"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."from_email" IS 'Sender address; null falls back to the marketing default.';


--
-- Name: COLUMN "email_agents"."reply_to"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."reply_to" IS 'Reply-to address; null falls back to the marketing default.';


--
-- Name: COLUMN "email_agents"."sources"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."sources" IS 'JSON list of the source keys the agent may read about a person: learner_progress, coaching, crm, past_emails, tags.';


--
-- Name: COLUMN "email_agents"."cadence_days"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."cadence_days" IS 'Days between messages to the same person.';


--
-- Name: COLUMN "email_agents"."send_hour"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."send_hour" IS 'Hour (0-23) to send, read in the person''s time zone, falling back to the brand''s.';


--
-- Name: COLUMN "email_agents"."review_mode"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."review_mode" IS 'Whether every message waits for a person or a sample releases the rest. Valid values: [hold_all, sample].';


--
-- Name: COLUMN "email_agents"."sample_size"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."sample_size" IS 'Messages per run a person reads before the rest release, when review_mode is sample.';


--
-- Name: COLUMN "email_agents"."max_words"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."max_words" IS 'Upper bound the validator enforces on the body.';


--
-- Name: COLUMN "email_agents"."active"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."active" IS 'Whether the cron runs it; false pauses the agent.';


--
-- Name: COLUMN "email_agents"."created_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."created_by" IS 'Email of the admin who created it.';


--
-- Name: COLUMN "email_agents"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."created_at" IS 'Row creation time.';


--
-- Name: COLUMN "email_agents"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."updated_at" IS 'Last modification time.';


--
-- Name: COLUMN "email_agents"."archived_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_agents"."archived_at" IS 'Soft-archive timestamp; an archived agent runs no more.';


--
-- Name: email_audiences; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."email_audiences" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "rules" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone
);


--
-- Name: TABLE "email_audiences"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."email_audiences" IS 'One row is: one saved email audience, a named set of rules resolved to people whenever a recipient list is built.';


--
-- Name: COLUMN "email_audiences"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_audiences"."id" IS 'Primary key.';


--
-- Name: COLUMN "email_audiences"."name"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_audiences"."name" IS 'What the audience is called in the broadcast and series pickers.';


--
-- Name: COLUMN "email_audiences"."rules"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_audiences"."rules" IS 'The rules as JSON: relationships (team, client, prospect, network), companyIds, tagIds, excludeTagIds. Every non-empty list must match; within a list any value matches. Consent and do-not-contact are applied on top at build and send time.';


--
-- Name: COLUMN "email_audiences"."created_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_audiences"."created_by" IS 'Email of the admin who created it.';


--
-- Name: COLUMN "email_audiences"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_audiences"."created_at" IS 'Row creation time.';


--
-- Name: COLUMN "email_audiences"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_audiences"."updated_at" IS 'Last modification time.';


--
-- Name: COLUMN "email_audiences"."archived_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_audiences"."archived_at" IS 'Soft-archive timestamp; null means the audience can be picked.';


--
-- Name: email_campaign_recipients; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."email_campaign_recipients" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "campaign_id" "uuid" NOT NULL,
    "person_id" "uuid" NOT NULL,
    "email" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "skip_reason" "text",
    "resend_email_id" "text",
    "error" "text",
    "sent_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "send_after" timestamp with time zone,
    CONSTRAINT "email_campaign_recipients_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'claimed'::"text", 'sent'::"text", 'skipped'::"text", 'failed'::"text"])))
);


--
-- Name: COLUMN "email_campaign_recipients"."send_after"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaign_recipients"."send_after" IS 'Earliest instant this recipient may be sent (their local send window, e.g. Tuesday 08:00 in their zone). Null: no window, send on the next tick.';


--
-- Name: email_campaigns; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."email_campaigns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "subject" "text" NOT NULL,
    "preheader" "text",
    "body_md" "text" DEFAULT ''::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "segment" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "from_email" "text",
    "reply_to" "text",
    "batch_size" integer DEFAULT 150 NOT NULL,
    "scheduled_at" timestamp with time zone,
    "approved_at" timestamp with time zone,
    "approved_by" "text",
    "sent_at" timestamp with time zone,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "brand_id" "uuid",
    "blocks" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "agent_step" "text",
    "agent_error" "text",
    "agent_started_at" timestamp with time zone,
    "agent_notes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "summary_posted_at" timestamp with time zone,
    "audience_id" "uuid",
    "series_id" "uuid",
    "archived_at" timestamp with time zone,
    "archived_by" "text",
    CONSTRAINT "email_campaigns_batch_size_check" CHECK ((("batch_size" >= 1) AND ("batch_size" <= 1000))),
    CONSTRAINT "email_campaigns_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'approved'::"text", 'sending'::"text", 'sent'::"text", 'cancelled'::"text", 'missed'::"text"])))
);


--
-- Name: COLUMN "email_campaigns"."blocks"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaigns"."blocks" IS 'Structured email sections beside the markdown body: featured blog posts (marketing_content ids, resolved at send time) and the call to action (tagline, line, label, url). Shape validated by broadcastBlocksSchema; {} means a plain letter.';


--
-- Name: COLUMN "email_campaigns"."agent_step"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaigns"."agent_step" IS 'Letter agent run pointer: the step to run next (gather, pick, write, rotate, assemble, validate), ready (parked for approval), or null (no run).';


--
-- Name: COLUMN "email_campaigns"."agent_error"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaigns"."agent_error" IS 'Why the letter agent stopped at agent_step; null while it runs or when parked.';


--
-- Name: COLUMN "email_campaigns"."agent_started_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaigns"."agent_started_at" IS 'When the current letter agent run started.';


--
-- Name: COLUMN "email_campaigns"."agent_notes"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaigns"."agent_notes" IS 'What the letter agent learned between steps: gathered data points with sources, the picked posts, the validate checklist. Shape owned by entities/company-os/modules/campaigns/letter/data.ts.';


--
-- Name: COLUMN "email_campaigns"."summary_posted_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaigns"."summary_posted_at" IS 'When the per-broadcast Lark summary was posted (72h after send). NULL means still owed; the summary routine sets it so a daily run posts each broadcast once.';


--
-- Name: COLUMN "email_campaigns"."audience_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaigns"."audience_id" IS 'FK to email_audiences; when set, the recipient list is built from this saved audience instead of segment personas.';


--
-- Name: COLUMN "email_campaigns"."series_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaigns"."series_id" IS 'FK to email_series; set on an issue the series cron opened. Approving an issue schedules it to send at scheduled_at.';


--
-- Name: COLUMN "email_campaigns"."archived_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaigns"."archived_at" IS 'Soft-delete timestamp; an archived broadcast leaves every list and calendar but keeps its recipients and events.';


--
-- Name: COLUMN "email_campaigns"."archived_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_campaigns"."archived_by" IS 'Email of the admin who deleted it.';


--
-- Name: email_events; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."email_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "resend_email_id" "text" NOT NULL,
    "event_type" "text" NOT NULL,
    "recipient" "text" NOT NULL,
    "person_id" "uuid",
    "campaign_id" "uuid",
    "subject" "text",
    "occurred_at" timestamp with time zone NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "svix_id" "text",
    "message_id" "uuid",
    CONSTRAINT "email_events_type_check" CHECK (("event_type" = ANY (ARRAY['sent'::"text", 'delivered'::"text", 'delivery_delayed'::"text", 'bounced'::"text", 'complained'::"text", 'opened'::"text", 'clicked'::"text", 'failed'::"text"])))
);


--
-- Name: COLUMN "email_events"."message_id"; Type: COMMENT; Schema: company_os; Owner: -
--

