--
-- Name: COLUMN "email_messages"."agent_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_messages"."agent_id" IS 'FK to email_agents.';


--
-- Name: COLUMN "email_messages"."skill_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_messages"."skill_id" IS 'FK to email_agent_skills; the version that wrote it.';


