--
-- Name: COLUMN "email_messages"."facts"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_messages"."facts" IS 'JSON list of the gathered facts the writer was given, each dated and sourced, shown beside the draft in review.';


--
-- Name: COLUMN "email_messages"."edited_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_messages"."edited_at" IS 'Set when a person changed the body before approving.';


