--
-- Name: COLUMN "email_series"."audience_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."audience_id" IS 'FK to email_audiences; the audience every issue is built for.';


--
-- Name: COLUMN "email_series"."brand_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."brand_id" IS 'FK to brands; the brand identity each issue sends as.';


--
