-- Name: COLUMN "email_series"."time_zone"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."time_zone" IS 'IANA zone the draft and send moments are read in, e.g. Australia/Perth.';


