-- Name: COLUMN "email_series"."send_hour"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."send_hour" IS 'Hour (0-23, in time_zone) the issue sends once approved.';


--
-- Name: COLUMN "email_series"."batch_size"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."batch_size" IS 'Emails per send tick for each issue.';


--
-- Name: COLUMN "email_series"."active"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."active" IS 'Whether the series cron opens new issues; false pauses the series.';


--
-- Name: COLUMN "email_series"."created_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."created_by" IS 'Email of the admin who created it.';


--
-- Name: COLUMN "email_series"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."created_at" IS 'Row creation time.';


--
-- Name: COLUMN "email_series"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."updated_at" IS 'Last modification time.';


