-- Name: COLUMN "email_series"."archived_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."archived_at" IS 'Soft-archive timestamp; an archived series opens no issues.';


