-- Name: COLUMN "email_series"."body_template"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."email_series"."body_template" IS 'Markdown body each new issue starts from. Filled when the issue opens: {next_coaching}, {latest_post}, {intro}. Filled per recipient at send: {first_name}, {certification_progress}, {coaching_progress}, {micro_session}.';


