-- Name: COLUMN "event_deliveries"."error"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."event_deliveries"."error" IS 'The handler''s error message when ok is false; null otherwise.';


