-- Name: COLUMN "event_deliveries"."duration_ms"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."event_deliveries"."duration_ms" IS 'Milliseconds the handler took.';


--
-- Name: COLUMN "event_deliveries"."delivered_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."event_deliveries"."delivered_at" IS 'When the handler finished (row insert time).';


--
-- Name: event_outbox; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."event_outbox" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
