-- Name: COLUMN "event_outbox"."attempts"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."event_outbox"."attempts" IS 'How many times it has been claimed for publishing.';


--
-- Name: COLUMN "event_outbox"."published_at"; Type: COMMENT; Schema: company_os; Owner: -
