--
-- Name: goals; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."goals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "coaching_profile_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "description_markdown" "text",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "quarter_label" "text",
    "objective_id" "uuid",
    "key_result_id" "uuid",
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metric_unit" "text",
    "start_value" numeric,
    "target_value" numeric,
    "current_value" numeric,
    "due_date" "date",
    "created_by" "uuid",
    "stretch_markdown" "text",
    "letter_md" "text",
    "letter_sealed_on" "date",
    "outcome_note" "text",
    "outcome_at" timestamp with time zone,
    "extended_from" "date",
    CONSTRAINT "coaching_goals_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'achieved'::"text", 'dropped'::"text", 'missed'::"text"]))),
    CONSTRAINT "goals_outcome_note_one_line" CHECK ((("outcome_note" IS NULL) OR ("char_length"("outcome_note") <= 200)))
);


--
-- Name: COLUMN "goals"."letter_md"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."goals"."letter_md" IS 'Two sentences the member wrote to their end-of-quarter self when they set this goal (L.10). Sealed until the quarter review opens: nothing may render it before then, which is what makes re-reading it land.';


--
-- Name: COLUMN "goals"."letter_sealed_on"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."goals"."letter_sealed_on" IS 'The Saigon date the letter was written. The seal is a rule about WHERE it renders, not a lock — this records when it was sealed so the quarter review can say how long ago.';


--
-- Name: COLUMN "goals"."outcome_note"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."goals"."outcome_note" IS 'The owner''s one line on why a goal was missed, written when they answered "did it land?" after its due date. Null unless status is missed.';


--
-- Name: COLUMN "goals"."outcome_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."goals"."outcome_at" IS 'When the owner recorded the goal''s ending (landed or missed) after its due date passed. Null while the goal is still running, and for goals ended before 2026-10-11.';


--
-- Name: COLUMN "goals"."extended_from"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."goals"."extended_from" IS 'The due date this goal had before its owner last extended it, so the card can say "extended from 30 Sep". Null if it was never extended.';


--
-- Name: hiring_shortlists; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."hiring_shortlists" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_requisition_id" "uuid" NOT NULL,
    "round" integer NOT NULL,
    "mode" "text" DEFAULT 'live'::"text" NOT NULL,
    "status" "text" DEFAULT 'proposed'::"text" NOT NULL,
    "items" "jsonb" NOT NULL,
    "version" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "decided_at" timestamp with time zone,
    CONSTRAINT "hiring_shortlists_items_check" CHECK (("jsonb_typeof"("items") = 'array'::"text")),
    CONSTRAINT "hiring_shortlists_mode_check" CHECK (("mode" = ANY (ARRAY['shadow'::"text", 'live'::"text"]))),
    CONSTRAINT "hiring_shortlists_round_check" CHECK (("round" > 0)),
    CONSTRAINT "hiring_shortlists_shadow_never_decided" CHECK ((("mode" = 'live'::"text") OR ("status" = ANY (ARRAY['proposed'::"text", 'withdrawn'::"text"])))),
    CONSTRAINT "hiring_shortlists_status_check" CHECK (("status" = ANY (ARRAY['proposed'::"text", 'approved'::"text", 'rejected'::"text", 'withdrawn'::"text", 'applied'::"text"])))
);


--
-- Name: TABLE "hiring_shortlists"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."hiring_shortlists" IS 'One row is: one shortlist the hiring chain proposed for one requisition in one round — each screened application in an advance, decline or hold lane — decided once by the approver. [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "hiring_shortlists"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."hiring_shortlists"."id" IS 'Primary key.';


--
-- Name: COLUMN "hiring_shortlists"."job_requisition_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."hiring_shortlists"."job_requisition_id" IS 'The requisition the shortlist is for.';


--
-- Name: COLUMN "hiring_shortlists"."round"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."hiring_shortlists"."round" IS '1 for the first shortlist of a requisition, one more for each after it.';


--
-- Name: COLUMN "hiring_shortlists"."mode"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."hiring_shortlists"."mode" IS 'Valid values: [shadow, live]. shadow rows are what a run in shadow mode would have proposed; they are never approved or applied.';


--
-- Name: COLUMN "hiring_shortlists"."status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."hiring_shortlists"."status" IS 'Valid values: [proposed, approved, rejected, withdrawn, applied]. proposed waits for the approver; applied once its lanes moved the applications.';


--
-- Name: COLUMN "hiring_shortlists"."items"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."hiring_shortlists"."items" IS 'The lanes, as an array of {application_id, lane, rating, flags, reason}; lane is advance, decline or hold.';


--
-- Name: COLUMN "hiring_shortlists"."version"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."hiring_shortlists"."version" IS 'A hash of the round and every item''s application and lane; the approval is for this version.';


--
-- Name: COLUMN "hiring_shortlists"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."hiring_shortlists"."created_at" IS 'Row insert time.';


--
-- Name: COLUMN "hiring_shortlists"."decided_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."hiring_shortlists"."decided_at" IS 'When it was approved, rejected, withdrawn or applied.';


