-- Name: COLUMN "idea_reactions"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."idea_reactions"."id" IS 'Primary key.';


--
-- Name: COLUMN "idea_reactions"."idea_id"; Type: COMMENT; Schema: company_os; Owner: -
