COMMENT ON COLUMN "company_os"."lark_user_connections"."access_token_expires_at" IS 'When the access token stops working.';


--
-- Name: COLUMN "lark_user_connections"."refresh_token_expires_at"; Type: COMMENT; Schema: company_os; Owner: -
