--
-- Name: COLUMN "notification_mutes"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_mutes"."created_at" IS 'When the person stopped updates about it.';


--
-- Name: notification_prefs; Type: TABLE; Schema: company_os; Owner: -
--

