    "person_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "muted" boolean DEFAULT false NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "notification_prefs_kind_check" CHECK (("kind" = ANY (ARRAY['card.completed'::"text", 'card.set_aside'::"text", 'subtask.done'::"text", 'leave.approved'::"text", 'leave.withdrawn'::"text", 'hire.made'::"text", 'deal.won'::"text", 'invoice.paid'::"text", 'idea.reacted'::"text", 'idea.built'::"text", 'idea.picked_up'::"text", 'claim.decided'::"text", 'claim.paid'::"text", 'idea.shipped'::"text", 'kudos.received'::"text", 'card.assigned'::"text", 'card.mentioned'::"text", 'card.commented'::"text", 'card.due_tomorrow'::"text", 'idea.set_aside'::"text", 'training.prep_ready'::"text", 'training.session_today'::"text", 'training.homework_due'::"text", 'training.note_updated'::"text", 'training.recap_ready'::"text", 'training.recap_published'::"text", 'training.weekly_recap_waiting'::"text", 'training.weekly_recap_held'::"text", 'approval.waiting'::"text", 'card.replied'::"text", 'blocker.handed'::"text", 'coaching.one_on_one'::"text", 'review.needs_you'::"text"])))
);


--
-- Name: TABLE "notification_prefs"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."notification_prefs" IS 'One row is: one person''s choice about one kind of inbox item. [master · Reference & rules | tier 3 support | active]';


--
-- Name: COLUMN "notification_prefs"."person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_prefs"."person_id" IS 'The person, referencing people.id.';


--
-- Name: COLUMN "notification_prefs"."kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_prefs"."kind" IS 'The inbox kind. Valid values: [card.completed, card.set_aside, subtask.done, leave.approved, leave.withdrawn, hire.made, deal.won, invoice.paid, idea.reacted, idea.built, idea.picked_up, claim.decided, claim.paid, idea.shipped, kudos.received, card.assigned, card.mentioned, card.commented, card.due_tomorrow, idea.set_aside, training.prep_ready, training.session_today, training.homework_due, training.note_updated, training.recap_ready, training.recap_published, training.weekly_recap_waiting, training.weekly_recap_held, approval.waiting, card.replied, blocker.handed, coaching.one_on_one, review.needs_you]';


--
-- Name: COLUMN "notification_prefs"."muted"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_prefs"."muted" IS 'True when this kind should not land in the person''s inbox.';


--
-- Name: COLUMN "notification_prefs"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_prefs"."updated_at" IS 'When the choice last changed; maintained by a trigger.';


--
-- Name: notification_queue; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."notification_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "kind" "text" NOT NULL,
    "channel" "text" NOT NULL,
    "recipient" "text" NOT NULL,
    "person_id" "uuid",
    "subject" "text" NOT NULL,
    "message" "jsonb" NOT NULL,
    "urgency" "text" DEFAULT 'normal'::"text" NOT NULL,
    "reason" "text" NOT NULL,
    "dedupe_key" "text" NOT NULL,
    "deliver_after" timestamp with time zone NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "sent_at" timestamp with time zone,
    "carried_by" "text",
    "error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "notification_queue_attempts_check" CHECK (("attempts" >= 0)),
    CONSTRAINT "notification_queue_channel_check" CHECK (("channel" = ANY (ARRAY['lark_dm'::"text", 'lark_chat'::"text", 'email'::"text"]))),
    CONSTRAINT "notification_queue_dedupe_key_check" CHECK (("btrim"("dedupe_key") <> ''::"text")),
    CONSTRAINT "notification_queue_kind_check" CHECK (("btrim"("kind") <> ''::"text")),
    CONSTRAINT "notification_queue_message_check" CHECK (("jsonb_typeof"("message") = 'object'::"text")),
    CONSTRAINT "notification_queue_reason_check" CHECK (("reason" = ANY (ARRAY['digest'::"text", 'held'::"text"]))),
    CONSTRAINT "notification_queue_recipient_check" CHECK (("btrim"("recipient") <> ''::"text")),
    CONSTRAINT "notification_queue_sent_says_when" CHECK ((("status" = 'sent'::"text") = ("sent_at" IS NOT NULL))),
    CONSTRAINT "notification_queue_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'sent'::"text", 'skipped'::"text", 'failed'::"text"]))),
    CONSTRAINT "notification_queue_subject_check" CHECK (("btrim"("subject") <> ''::"text")),
    CONSTRAINT "notification_queue_urgency_check" CHECK (("urgency" = ANY (ARRAY['normal'::"text", 'urgent'::"text"])))
);


--
-- Name: TABLE "notification_queue"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."notification_queue" IS 'One row is: one notice the notification router did not send at once, either held through quiet hours or waiting for its recipient''s morning digest, and what became of it. [other · System config & plumbing | tier 3 support | active]';


--
-- Name: COLUMN "notification_queue"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."id" IS 'Primary key.';


--
-- Name: COLUMN "notification_queue"."kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."kind" IS 'The router kind that queued it (the registry in kernel/messaging/router.ts), e.g. ops.qbo-token-expiring.';


--
-- Name: COLUMN "notification_queue"."channel"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."channel" IS 'Valid values: [lark_dm, lark_chat, email]. How it is delivered: a Lark direct message, a post to a Lark group chat, or an email.';


--
-- Name: COLUMN "notification_queue"."recipient"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."recipient" IS 'Who receives it: an email address for lark_dm and email, or the chat''s name (ops, revenue, product, eo, coaching) for lark_chat.';


--
-- Name: COLUMN "notification_queue"."person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."person_id" IS 'The recipient''s person, referencing people.id, when the address resolves to one; null for a group chat or an address with no person.';


--
-- Name: COLUMN "notification_queue"."subject"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."subject" IS 'One line saying what the notice is about; the digest lists it, and the log''s subject comes from it.';


--
-- Name: COLUMN "notification_queue"."message"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."message" IS 'The notice itself as JSON: {"text": "..."} for a text message or {"card": {...}} for a Lark card.';


--
-- Name: COLUMN "notification_queue"."urgency"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."urgency" IS 'Valid values: [normal, urgent]. What the caller asked for; an urgent notice is never held for quiet hours.';


--
-- Name: COLUMN "notification_queue"."reason"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."reason" IS 'Valid values: [digest, held]. digest when its kind is delivered in the morning digest; held when an immediate kind landed in quiet hours.';


--
-- Name: COLUMN "notification_queue"."dedupe_key"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."dedupe_key" IS 'The caller''s idempotency key for the notice; unique, so the same notice queued twice is one row. A held row is sent under this key in automation_effects.';


--
-- Name: COLUMN "notification_queue"."deliver_after"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."deliver_after" IS 'The earliest moment it may be sent: the start of the next working window for a held row, the next working morning for a digest row.';


--
-- Name: COLUMN "notification_queue"."status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."status" IS 'Valid values: [queued, sent, skipped, failed]. queued until the flush handles it; sent when it was delivered; skipped when delivery was declined on purpose (the recipient opted out of Lark DMs, or the chat is not configured); failed when the flush gave up after repeated failures.';


--
-- Name: COLUMN "notification_queue"."attempts"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."attempts" IS 'How many times the flush has tried to send it.';


--
-- Name: COLUMN "notification_queue"."sent_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."sent_at" IS 'When it was delivered; set exactly when status is sent.';


--
-- Name: COLUMN "notification_queue"."carried_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."carried_by" IS 'The automation_effects key of the send that delivered it: its own dedupe key for a held row, the digest''s key (messaging:digest:<recipient>:<date>) for a digest row.';


--
-- Name: COLUMN "notification_queue"."error"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."error" IS 'Why the last attempt failed or was skipped; null otherwise.';


--
-- Name: COLUMN "notification_queue"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_queue"."created_at" IS 'When notify() queued it.';


--
-- Name: notification_reads; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."notification_reads" (
    "notification_id" "uuid" NOT NULL,
    "person_id" "uuid" NOT NULL,
    "read_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "done_at" timestamp with time zone,
    "snoozed_until" timestamp with time zone
);


--
-- Name: TABLE "notification_reads"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."notification_reads" IS 'One row is: one inbox item its person has read. [other · Logs, audit & telemetry | tier 3 support | active]';


--
-- Name: COLUMN "notification_reads"."notification_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_reads"."notification_id" IS 'The item that was read, referencing notifications.id; one read per item.';


--
-- Name: COLUMN "notification_reads"."person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_reads"."person_id" IS 'The person who read it, referencing people.id; always the item''s own person.';


--
-- Name: COLUMN "notification_reads"."read_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_reads"."read_at" IS 'When it was read.';


--
-- Name: COLUMN "notification_reads"."done_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_reads"."done_at" IS 'When the person marked the item done; null until then. Done takes an item off Needs you; read only marks it seen. Clearing it is undo.';


--
-- Name: COLUMN "notification_reads"."snoozed_until"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notification_reads"."snoozed_until" IS 'When a snoozed ask comes back ("Remind me tomorrow"); null when nothing is snoozed. Until then the ask is out of From teammates and the count; it returns on its own.';


--
-- Name: notifications; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."notifications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "person_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "title" "text" NOT NULL,
