    CONSTRAINT "notifications_subject_shape" CHECK ((("subject" IS NULL) OR ("subject" ~ '^(card|idea):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::"text"))),
    CONSTRAINT "notifications_title_check" CHECK (("btrim"("title") <> ''::"text"))
);


--
-- Name: TABLE "notifications"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."notifications" IS 'One row is: one fact that matters to one person, in their inbox — a card of theirs finished or set aside by someone else, a subtask ticked on their card, their leave approved, a hire on their requisition, a deal they own won, an invoice of a company they own paid. [other · Logs, audit & telemetry | tier 3 support | active]';


--
-- Name: COLUMN "notifications"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."id" IS 'Primary key.';


--
-- Name: COLUMN "notifications"."person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."person_id" IS 'The person the fact matters to, referencing people.id.';


--
-- Name: COLUMN "notifications"."kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."kind" IS 'What kind of fact it is. Valid values: [card.completed, card.set_aside, subtask.done, leave.approved, leave.withdrawn, hire.made, deal.won, invoice.paid, idea.reacted, idea.built, idea.picked_up, claim.decided, claim.paid, idea.shipped, kudos.received, card.assigned, card.mentioned, card.commented, card.due_tomorrow, idea.set_aside, training.prep_ready, training.session_today, training.homework_due, training.note_updated, training.recap_ready, training.recap_published, training.weekly_recap_waiting, training.weekly_recap_held, approval.waiting, card.replied, blocker.handed, coaching.one_on_one, review.needs_you]';


--
-- Name: COLUMN "notifications"."title"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."title" IS 'The sentence the inbox shows.';


--
-- Name: COLUMN "notifications"."body"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."body" IS 'A second line when the fact has one (the leave''s dates, the amount).';


--
-- Name: COLUMN "notifications"."admin_href"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."admin_href" IS 'Where the item opens on the admin surface.';


--
-- Name: COLUMN "notifications"."team_href"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."team_href" IS 'Where the item opens on the team surface.';


--
-- Name: COLUMN "notifications"."event_key"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."event_key" IS 'What the row dedupes on within its kind (the card, the request, the deal), so a fact announced twice lands once.';


--
-- Name: COLUMN "notifications"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."created_at" IS 'When the fact was written to the inbox.';


--
-- Name: COLUMN "notifications"."subject"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."subject" IS 'The card or spark the row is about, as card:<tasks.id> or idea:<ideas.id>, so the inbox can show several rows about one card as one line and a person can stop updates about it. Null for rows about anything else.';


--
-- Name: COLUMN "notifications"."actor_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."notifications"."actor_id" IS 'The person whose action raised the row, referencing people.id, so the inbox can show their face. Null for a routine''s row, a decision with no one person behind it, and rows written before 2026-10-10.';


