    "company_id" "uuid" NOT NULL,
    "meeting_id" "uuid",
    "deal_id" "uuid",
    "mode" "text" NOT NULL,
    "step" "text" DEFAULT 'gather'::"text" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finished_at" timestamp with time zone,
    "error" "text",
    "inputs" "jsonb",
    "screen" "jsonb",
    "facts" "jsonb",
    "crm_patch" "jsonb",
    "crm_applied" "jsonb",
    "ai_sections" "jsonb",
    "sections" "jsonb",
    "amount_cents" bigint,
    "currency" "text",
    "line_items" "jsonb",
    "slug" "text",
    "html" "text",
    "lint" "jsonb",
    "version" "text",
    "published_url" "text",
    "published_at" timestamp with time zone,
    "requested_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "proposal_drafts_amount_shape" CHECK (((("amount_cents" IS NULL) OR ("amount_cents" >= 0)) AND (("currency" IS NULL) OR ("currency" ~ '^[a-z]{3}$'::"text")) AND (("slug" IS NULL) OR ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::"text")))),
    CONSTRAINT "proposal_drafts_mode_check" CHECK (("mode" = ANY (ARRAY['shadow'::"text", 'live'::"text"]))),
    CONSTRAINT "proposal_drafts_mode_steps" CHECK (((("step" <> 'shadow-done'::"text") OR ("mode" = 'shadow'::"text")) AND (("step" <> ALL (ARRAY['ask'::"text", 'ready'::"text", 'publish'::"text", 'record'::"text", 'done'::"text"])) OR ("mode" = 'live'::"text")))),
    CONSTRAINT "proposal_drafts_published_is_whole" CHECK (((("published_at" IS NULL) = ("published_url" IS NULL)) AND (("published_url" IS NULL) OR (("html" IS NOT NULL) AND ("version" IS NOT NULL) AND ("slug" IS NOT NULL))))),
    CONSTRAINT "proposal_drafts_step_check" CHECK (("step" = ANY (ARRAY['gather'::"text", 'extract'::"text", 'draft'::"text", 'ask'::"text", 'ready'::"text", 'publish'::"text", 'record'::"text", 'done'::"text", 'rejected'::"text", 'stopped'::"text", 'shadow-done'::"text"]))),
    CONSTRAINT "proposal_drafts_stopped_says_why" CHECK ((("step" <> 'stopped'::"text") OR ("length"("btrim"(COALESCE("error", ''::"text"))) > 0)))
);


--
-- Name: TABLE "proposal_drafts"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."proposal_drafts" IS 'One row is: one proposal the proposal chain drafted from one sales call (company and meeting) — the facts it was drafted from, the sections the client would read, where its run is, and whether it was approved and published. [transactional · Revenue documents | tier 3 support | active]';


--
-- Name: COLUMN "proposal_drafts"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."id" IS 'Primary key.';


--
-- Name: COLUMN "proposal_drafts"."company_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."company_id" IS 'The client company the proposal is for.';


--
-- Name: COLUMN "proposal_drafts"."meeting_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."meeting_id" IS 'The sales call the proposal was drafted from; unique with company_id. Set null when the meeting is deleted, which stops a run in flight and keeps a published proposal.';


--
-- Name: COLUMN "proposal_drafts"."deal_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."deal_id" IS 'The deal the proposal is attached to, whose proposal_url the publish step sets; null until a deal is chosen or created. Set null when the deal is deleted.';


--
-- Name: COLUMN "proposal_drafts"."mode"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."mode" IS 'Whether the run acts. shadow drafts and stops at shadow-done, opening no approval and publishing nothing; live asks for approval and publishes once approved. Set from the routine switch when the run starts. Valid values: [shadow, live]';


--
-- Name: COLUMN "proposal_drafts"."step"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."step" IS 'Where the run is (ADR 0015). gather, extract, draft, ask, publish and record are advanced by the tick driver; ready waits on the Revenue approver''s decision; done is published; rejected is closed unpublished; stopped carries its error until a person retries; shadow-done ends a shadow run. Valid values: [gather, extract, draft, ask, ready, publish, record, done, rejected, stopped, shadow-done]';


--
-- Name: COLUMN "proposal_drafts"."started_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."started_at" IS 'The run''s epoch, part of every step''s tick key; reset when a person retries or drafts again, so a fresh run gets fresh ticks.';


--
-- Name: COLUMN "proposal_drafts"."finished_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."finished_at" IS 'When the run reached done, rejected, stopped or shadow-done; null while it runs.';


--
-- Name: COLUMN "proposal_drafts"."error"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."error" IS 'Why the run stopped (the last step''s error after its attempts, or the meeting gone); required when step is stopped, cleared on retry.';


--
-- Name: COLUMN "proposal_drafts"."inputs"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."inputs" IS 'What the gather step read, by reference: the meeting, company, deal and people ids and the transcript''s hash; never the transcript itself.';


--
-- Name: COLUMN "proposal_drafts"."screen"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."screen" IS 'The input screening result for the transcript (flagged instruction-shaped lines, whether it was cut and at what length), shown on the review page.';


--
-- Name: COLUMN "proposal_drafts"."facts"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."facts" IS 'What the extract step read from the call (pains, budget said, timeline, decision makers, next step, normalised product names), each with the transcript line it rests on.';


--
-- Name: COLUMN "proposal_drafts"."crm_patch"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."crm_patch" IS 'The CRM changes the extract step proposes (deal fields, lifecycle, contacts matched or new), applied only when a person ticks them.';


--
-- Name: COLUMN "proposal_drafts"."crm_applied"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."crm_applied" IS 'Which parts of crm_patch a person applied and when; an applied part is not offered again.';


--
-- Name: COLUMN "proposal_drafts"."ai_sections"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."ai_sections" IS 'The proposal sections exactly as the model wrote them, kept so the approver''s edit can be learned from.';


--
-- Name: COLUMN "proposal_drafts"."sections"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."sections" IS 'The proposal sections the client will read; equal to ai_sections until a person edits them.';


--
-- Name: COLUMN "proposal_drafts"."amount_cents"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."amount_cents" IS 'The proposal''s total value in the currency''s minor unit; never negative.';


--
-- Name: COLUMN "proposal_drafts"."currency"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."currency" IS 'Lowercase ISO 4217 code of amount_cents and the line items, as deals keeps it ("usd", "aud").';


--
-- Name: COLUMN "proposal_drafts"."line_items"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."line_items" IS 'The priced lines the total is made of, each with its amount in minor units.';


--
-- Name: COLUMN "proposal_drafts"."slug"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."slug" IS 'The unguessable URL-safe name the published page is served at, /proposals/d/<slug>; unique.';


--
-- Name: COLUMN "proposal_drafts"."html"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."html" IS 'The page the client would read, rendered from the fixed proposal template; served only once the row is published.';


--
-- Name: COLUMN "proposal_drafts"."lint"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."lint" IS 'The house-style and price-band findings on the current sections, shown to the approver; never corrected silently.';


--
-- Name: COLUMN "proposal_drafts"."version"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."version" IS 'The content hash of the sections, amount, currency, line items, slug, deal and company that the open approval names; publishing goes ahead only when the approved version equals it.';


--
-- Name: COLUMN "proposal_drafts"."published_url"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."published_url" IS 'The live URL the publish step set on the deal; set together with published_at, and only with html, version and slug.';


--
-- Name: COLUMN "proposal_drafts"."published_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."published_at" IS 'When the proposal went live in the client''s portal; set together with published_url.';


--
-- Name: COLUMN "proposal_drafts"."requested_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."requested_by" IS 'The person who pressed Draft a proposal; null when the driver''s discovery read started the run.';


--
-- Name: COLUMN "proposal_drafts"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."created_at" IS 'When the row was inserted.';


--
-- Name: COLUMN "proposal_drafts"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."proposal_drafts"."updated_at" IS 'When the row last changed, stamped by the writer.';


--
-- Name: qbo_connection; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."qbo_connection" (
    "id" "text" DEFAULT 'edge8'::"text" NOT NULL,
    "realm_id" "text" NOT NULL,
    "access_token" "text" NOT NULL,
    "refresh_token" "text" NOT NULL,
    "access_token_expires_at" timestamp with time zone NOT NULL,
    "refresh_token_expires_at" timestamp with time zone NOT NULL,
    "environment" "text" DEFAULT 'production'::"text" NOT NULL,
    "connected_by" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "qbo_connection_environment_check" CHECK (("environment" = ANY (ARRAY['sandbox'::"text", 'production'::"text"])))
);


--
-- Name: quest_hands; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."quest_hands" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "person_id" "uuid" NOT NULL,
    "topic" "text" NOT NULL,
    "topic_key" "text" GENERATED ALWAYS AS ("regexp_replace"("lower"("btrim"("topic")), '\s+'::"text", ' '::"text", 'g'::"text")) STORED,
    "quest_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "quest_hands_topic_not_blank" CHECK (("btrim"("topic") <> ''::"text"))
);


--
-- Name: TABLE "quest_hands"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."quest_hands" IS 'One row is: one raised hand — one person saying they want to learn one topic. Three hands on a topic make a cold fire on the Quests page; the row stays under the Raid once the fire is lit, and a hand taken back is a row deleted.';


--
-- Name: COLUMN "quest_hands"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_hands"."id" IS 'Primary key.';


--
-- Name: COLUMN "quest_hands"."person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_hands"."person_id" IS 'Who raised the hand (company_os.people). Seen by nobody but the count; the page never names who wants a topic.';


--
-- Name: COLUMN "quest_hands"."topic"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_hands"."topic" IS 'The topic as the first hand typed it, trimmed and never blank; the words the cold fire shows.';


--
-- Name: COLUMN "quest_hands"."topic_key"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_hands"."topic_key" IS 'The topic normalised (lower case, trimmed, inner spaces collapsed), generated, so hands on the same topic meet under one key.';


--
-- Name: COLUMN "quest_hands"."quest_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_hands"."quest_id" IS 'The Raid this topic became once someone lit it; null while the topic is still wanted.';


--
-- Name: COLUMN "quest_hands"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_hands"."created_at" IS 'When the hand was raised.';


--
-- Name: quest_heads; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."quest_heads" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quest_id" "uuid" NOT NULL,
    "position" smallint NOT NULL,
    "ask" "text" NOT NULL,
    "closes_at" timestamp with time zone NOT NULL,
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "quest_heads_ask_check" CHECK (("length"(TRIM(BOTH FROM "ask")) > 0)),
    CONSTRAINT "quest_heads_position_check" CHECK (("position" >= 1))
);


--
-- Name: TABLE "quest_heads"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."quest_heads" IS 'One row is: one head of a Bounty — one ask with its own due time. A Bounty has one or more; two or more make a Hydra. A Standing and a Turn-in are per head. [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "quest_heads"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_heads"."id" IS 'Primary key.';


--
-- Name: COLUMN "quest_heads"."quest_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_heads"."quest_id" IS 'The Bounty (quests) this head belongs to.';


--
-- Name: COLUMN "quest_heads"."position"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_heads"."position" IS 'The head''s place in the order the Giver wrote them, from 1; once per quest.';


--
-- Name: COLUMN "quest_heads"."ask"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_heads"."ask" IS 'What this head asks for, in the Giver''s words.';


--
-- Name: COLUMN "quest_heads"."closes_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_heads"."closes_at" IS 'The head''s due time (a date and a time of day, shown in Saigon): after it the head stops expecting Turn-ins, and a Turn-in is late and still counts.';


--
-- Name: COLUMN "quest_heads"."closed_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_heads"."closed_at" IS 'When the head closed, by its due time or early by the Giver; null while open.';


--
-- Name: COLUMN "quest_heads"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_heads"."created_at" IS 'When the head was written, with its quest.';


--
-- Name: COLUMN "quest_heads"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_heads"."updated_at" IS 'When the row last changed.';


--
-- Name: quest_party; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."quest_party" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quest_id" "uuid" NOT NULL,
    "person_id" "uuid" NOT NULL,
    "standing" "text" DEFAULT 'called'::"text" NOT NULL,
    "called_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "accepted_at" timestamp with time zone,
    "turned_in_at" timestamp with time zone,
    "late" boolean DEFAULT false NOT NULL,
    "handed_back_at" timestamp with time zone,
    "missed_at" timestamp with time zone,
    "turn_in_text" "text",
    "turn_in_url" "text",
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "head_id" "uuid" NOT NULL,
    "reminded_at" timestamp with time zone,
    CONSTRAINT "quest_party_handed_back_shape" CHECK ((("standing" <> 'handed_back'::"text") OR ("handed_back_at" IS NOT NULL))),
    CONSTRAINT "quest_party_late_only_when_turned_in" CHECK (((NOT "late") OR ("standing" = 'turned_in'::"text"))),
    CONSTRAINT "quest_party_missed_shape" CHECK ((("standing" <> 'missed'::"text") OR ("missed_at" IS NOT NULL))),
    CONSTRAINT "quest_party_standing_check" CHECK (("standing" = ANY (ARRAY['called'::"text", 'accepted'::"text", 'turned_in'::"text", 'handed_back'::"text", 'missed'::"text"]))),
    CONSTRAINT "quest_party_turned_in_shape" CHECK ((("standing" <> 'turned_in'::"text") OR ("turned_in_at" IS NOT NULL)))
);


--
-- Name: TABLE "quest_party"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."quest_party" IS 'One row is: one person on one quest, with their Standing and their Turn-in. A Missed is read only by the person, their managers, admins and a Giver who is a manager, one quest at a time (ADR 0020). [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "quest_party"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."id" IS 'Primary key.';


--
-- Name: COLUMN "quest_party"."quest_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."quest_id" IS 'The quest (quests).';


--
-- Name: COLUMN "quest_party"."person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."person_id" IS 'The person (company_os.people) on the quest; once per head. Only staff are ever called.';


--
-- Name: COLUMN "quest_party"."standing"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."standing" IS 'Where this person is on this quest, written only by the quests entity''s code, never by a trigger. Valid values: [called, accepted, turned_in, handed_back, missed]';


--
-- Name: COLUMN "quest_party"."called_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."called_at" IS 'When the person was called, or joined.';


--
-- Name: COLUMN "quest_party"."accepted_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."accepted_at" IS 'When the person accepted; a Turn-in without an accept sets it too, because turning in counts as accepting.';


--
-- Name: COLUMN "quest_party"."turned_in_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."turned_in_at" IS 'When the person turned in.';


--
-- Name: COLUMN "quest_party"."late"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."late" IS 'True when the Turn-in arrived after the head''s due time or after the head closed; it counts in full.';


--
-- Name: COLUMN "quest_party"."handed_back_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."handed_back_at" IS 'When the person handed the quest back.';


--
-- Name: COLUMN "quest_party"."missed_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."missed_at" IS 'When the head closed with this person still out (on an optional Bounty, only after they accepted); kept as history when a late Turn-in lifts the Missed.';


--
-- Name: COLUMN "quest_party"."turn_in_text"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."turn_in_text" IS 'The Turn-in''s text, in the person''s words.';


--
-- Name: COLUMN "quest_party"."turn_in_url"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."turn_in_url" IS 'The Turn-in''s link, where the quest wants one (a Beacon always does).';


--
-- Name: COLUMN "quest_party"."note"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."note" IS 'The person''s note to the Giver when they handed the head back; may be empty when they declined an optional Bounty.';


--
-- Name: COLUMN "quest_party"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."created_at" IS 'When the row was inserted.';


--
-- Name: COLUMN "quest_party"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."updated_at" IS 'When the row last changed.';


--
-- Name: COLUMN "quest_party"."head_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."head_id" IS 'The head (quest_heads) of the same quest this row answers; once per person per head.';


--
-- Name: COLUMN "quest_party"."reminded_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_party"."reminded_at" IS 'When the person was reminded, two hours before the head''s due time, while still out; written once per person per head by the reminder routine, so a reminder never doubles. Null until then.';


--
-- Name: quest_reactions; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."quest_reactions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quest_id" "uuid" NOT NULL,
    "party_id" "uuid" NOT NULL,
    "party_standing" "text" DEFAULT 'turned_in'::"text" NOT NULL,
    "line" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "quest_reactions_line_check" CHECK (("length"(TRIM(BOTH FROM "line")) > 0)),
    CONSTRAINT "quest_reactions_party_standing_check" CHECK (("party_standing" = 'turned_in'::"text"))
);


--
-- Name: TABLE "quest_reactions"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."quest_reactions" IS 'One row is: the Giver''s Reaction to one Turn-in — a line that makes the hit a critical. At most one per Turn-in. [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "quest_reactions"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_reactions"."id" IS 'Primary key.';


--
-- Name: COLUMN "quest_reactions"."quest_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_reactions"."quest_id" IS 'The quest (quests); half of the foreign key onto the party row, so a Reaction is on a Turn-in of the same quest.';


--
-- Name: COLUMN "quest_reactions"."party_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_reactions"."party_id" IS 'The party row (quest_party) whose Turn-in the Giver reacted to; once per row.';


--
-- Name: COLUMN "quest_reactions"."party_standing"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_reactions"."party_standing" IS 'Always turned_in: part of the foreign key onto quest_party (id, quest_id, standing), so a Reaction exists only on a Turn-in and that row cannot leave turned_in while it stands. Valid values: [turned_in]';


--
-- Name: COLUMN "quest_reactions"."line"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_reactions"."line" IS 'The Giver''s line, as the person who turned in reads it.';


--
-- Name: COLUMN "quest_reactions"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quest_reactions"."created_at" IS 'When the Giver reacted.';


--
-- Name: quests; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."quests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "kind" "text" NOT NULL,
    "title" "text" NOT NULL,
    "ask" "text" DEFAULT ''::"text" NOT NULL,
    "giver_id" "uuid" NOT NULL,
    "closing_date" "date",
    "learning" boolean DEFAULT false NOT NULL,
    "state" "text" DEFAULT 'open'::"text" NOT NULL,
    "closed_at" timestamp with time zone,
    "withdrawn_at" timestamp with time zone,
    "host_id" "uuid",
    "training_id" "uuid",
    "lit_url" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "required" boolean DEFAULT false NOT NULL,
    "origin_idea_id" "uuid",
    "origin_quest_id" "uuid",
    CONSTRAINT "quests_bounty_has_closing_date" CHECK ((("kind" <> 'bounty'::"text") OR ("closing_date" IS NOT NULL))),
    CONSTRAINT "quests_closed_shape" CHECK ((("state" = 'closed'::"text") = ("closed_at" IS NOT NULL))),
    CONSTRAINT "quests_host_only_on_raid" CHECK ((("host_id" IS NULL) OR ("kind" = 'raid'::"text"))),
    CONSTRAINT "quests_kind_check" CHECK (("kind" = ANY (ARRAY['bounty'::"text", 'raid'::"text", 'beacon'::"text"]))),
    CONSTRAINT "quests_lit_url_only_on_beacon" CHECK ((("lit_url" IS NULL) OR ("kind" = 'beacon'::"text"))),
    CONSTRAINT "quests_state_check" CHECK (("state" = ANY (ARRAY['open'::"text", 'closed'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "quests_title_check" CHECK (("length"(TRIM(BOTH FROM "title")) > 0)),
    CONSTRAINT "quests_training_only_on_raid" CHECK ((("training_id" IS NULL) OR ("kind" = 'raid'::"text"))),
    CONSTRAINT "quests_withdrawn_shape" CHECK ((("state" = 'withdrawn'::"text") = ("withdrawn_at" IS NOT NULL)))
);


--
-- Name: TABLE "quests"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."quests" IS 'One row is: one quest — a Bounty (an ask with a closing date), a Raid (a session to teach the team) or a Beacon (a learning carried outside Edge8) — posted by its Giver. [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "quests"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."id" IS 'Primary key.';


--
-- Name: COLUMN "quests"."kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."kind" IS 'Which kind of quest it is. Valid values: [bounty, raid, beacon]';


--
-- Name: COLUMN "quests"."title"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."title" IS 'What the quest is called, as its party sees it.';


--
-- Name: COLUMN "quests"."ask"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."ask" IS 'What the Giver asks for, in their words; empty when the title says it all.';


--
-- Name: COLUMN "quests"."giver_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."giver_id" IS 'The Giver (company_os.people) who posted the quest.';


--
-- Name: COLUMN "quests"."closing_date"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."closing_date" IS 'The Saigon calendar date of the latest head''s due time, kept so readers of the first expand find a value; each head''s own due time is quest_heads.closes_at. Always set on a Bounty; null for an open-ended Raid or Beacon. To be dropped by a later contract migration.';


--
-- Name: COLUMN "quests"."learning"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."learning" IS 'True on a learning bounty: its Turn-ins become Discoveries in the Lore unless their author keeps them out.';


--
-- Name: COLUMN "quests"."state"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."state" IS 'Open until it closes (by its date or early by the Giver) or the Giver withdraws it; a withdrawn quest has no Missed. Valid values: [open, closed, withdrawn]';


--
-- Name: COLUMN "quests"."closed_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."closed_at" IS 'When the quest closed; set exactly when state is closed.';


--
-- Name: COLUMN "quests"."withdrawn_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."withdrawn_at" IS 'When the Giver withdrew the quest; set exactly when state is withdrawn.';


--
-- Name: COLUMN "quests"."host_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."host_id" IS 'A Raid''s Host (company_os.people), who teaches it; null on a cold campfire waiting for one, and on every Bounty and Beacon.';


--
-- Name: COLUMN "quests"."training_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."training_id" IS 'A Raid''s session (trainings), created through Training''s door when the campfire is lit; null otherwise.';


--
-- Name: COLUMN "quests"."lit_url"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."lit_url" IS 'A Beacon''s link to the public thing, once lit; null otherwise.';


--
-- Name: COLUMN "quests"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."created_at" IS 'When the quest was posted.';


--
-- Name: COLUMN "quests"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."updated_at" IS 'When the row last changed.';


--
-- Name: COLUMN "quests"."required"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."required" IS 'True when the Giver was a manager or an admin when they summoned it: being called is the commitment, there is no Accept move and no hand-back, and everyone still out at a head''s due time is Missed. False on an optional Bounty, where a person opts in by accepting and only an accepted person still out is Missed.';


--
-- Name: COLUMN "quests"."origin_idea_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."origin_idea_id" IS 'The learning spark (ideas) a Raid or a Beacon grew from through Evolve; null when it did not.';


--
-- Name: COLUMN "quests"."origin_quest_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."quests"."origin_quest_id" IS 'The held Raid a Beacon grew from through Evolve; null when it did not.';


--
-- Name: reimbursement_claim_events; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."reimbursement_claim_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "claim_id" "uuid" NOT NULL,
    "from_status" "text",
    "to_status" "text" NOT NULL,
    "actor_person_id" "uuid",
    "reason" "text",
    "declined_item_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "reimbursement_claim_events_from_status_check" CHECK ((("from_status" IS NULL) OR ("from_status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'checked'::"text", 'sent_back'::"text", 'rejected'::"text", 'approved'::"text", 'in_run'::"text", 'paid'::"text"])))),
    CONSTRAINT "reimbursement_claim_events_to_status_check" CHECK (("to_status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'checked'::"text", 'sent_back'::"text", 'rejected'::"text", 'approved'::"text", 'in_run'::"text", 'paid'::"text"])))
);


--
-- Name: TABLE "reimbursement_claim_events"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."reimbursement_claim_events" IS 'One row is: one transition of one claim — submitted, withdrawn, checked, sent back, rejected, approved, taken into a run, paid or returned to approved — with who did it and why. [other · Logs, audit & telemetry | tier 3 support | active]';


--
-- Name: COLUMN "reimbursement_claim_events"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_events"."id" IS 'Primary key.';


--
-- Name: COLUMN "reimbursement_claim_events"."claim_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_events"."claim_id" IS 'The claim (reimbursement_claims) that moved.';


--
-- Name: COLUMN "reimbursement_claim_events"."from_status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_events"."from_status" IS 'The status it left; null for a claim''s first event. Valid values: [draft, submitted, checked, sent_back, rejected, approved, in_run, paid]';


--
-- Name: COLUMN "reimbursement_claim_events"."to_status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_events"."to_status" IS 'The status it reached. Valid values: [draft, submitted, checked, sent_back, rejected, approved, in_run, paid]';


--
-- Name: COLUMN "reimbursement_claim_events"."actor_person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_events"."actor_person_id" IS 'The person (company_os.people) who moved it; null for the payment-run cron.';


--
-- Name: COLUMN "reimbursement_claim_events"."reason"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_events"."reason" IS 'The reason given when the move needs one (sent back, rejected, returned to approved).';


--
-- Name: COLUMN "reimbursement_claim_events"."declined_item_ids"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_events"."declined_item_ids" IS 'The items declined in this decision, if any.';


--
-- Name: COLUMN "reimbursement_claim_events"."metadata"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_events"."metadata" IS 'Detail of the move: the approved total at approval, the run, the payment.';


--
-- Name: COLUMN "reimbursement_claim_events"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_events"."created_at" IS 'When the move happened.';


--
-- Name: reimbursement_claim_items; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."reimbursement_claim_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "claim_id" "uuid" NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    "description" "text",
    "seller" "text",
    "bought_on" "date",
    "category" "text" NOT NULL,
    "bought_in_vietnam" boolean NOT NULL,
    "amount_cents" bigint NOT NULL,
    "currency" "text" NOT NULL,
    "amount_vnd" bigint,
    "fx_rate" numeric,
    "fx_source" "text" DEFAULT 'none'::"text" NOT NULL,
    "fx_as_of" "date",
    "charged_vnd" bigint,
    "lost_receipt_note" "text",
    "ai_reading" "jsonb",
    "ai_flags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "duplicate_of_item_id" "uuid",
    "declined_at" timestamp with time zone,
    "declined_by" "uuid",
    "decline_reason" "text",
    "rebill" boolean DEFAULT false NOT NULL,
    "rebill_company_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "removed_at" timestamp with time zone,
    "removed_by" "uuid",
    "remove_reason" "text",
    CONSTRAINT "reimbursement_claim_items_ai_flags_check" CHECK (("ai_flags" <@ ARRAY['buyer_not_organisation'::"text", 'buyer_tax_code_differs'::"text", 'unreadable'::"text", 'possible_duplicate'::"text", 'older_than_90_days'::"text", 'not_a_red_invoice'::"text"])),
    CONSTRAINT "reimbursement_claim_items_amount_cents_check" CHECK (("amount_cents" >= 0)),
    CONSTRAINT "reimbursement_claim_items_amount_vnd_check" CHECK ((("amount_vnd" IS NULL) OR ("amount_vnd" >= 0))),
    CONSTRAINT "reimbursement_claim_items_category_check" CHECK (("category" = ANY (ARRAY['transport'::"text", 'flights'::"text", 'accommodation'::"text", 'meals_travel'::"text", 'client_entertainment'::"text", 'software'::"text", 'equipment'::"text", 'training_events'::"text", 'other'::"text"]))),
    CONSTRAINT "reimbursement_claim_items_charged_vnd_check" CHECK ((("charged_vnd" IS NULL) OR ("charged_vnd" >= 0))),
    CONSTRAINT "reimbursement_claim_items_currency_check" CHECK (("currency" ~ '^[a-z]{3}$'::"text")),
    CONSTRAINT "reimbursement_claim_items_declined_shape" CHECK ((("declined_at" IS NULL) = ("decline_reason" IS NULL))),
    CONSTRAINT "reimbursement_claim_items_fx_rate_check" CHECK ((("fx_rate" IS NULL) OR ("fx_rate" > (0)::numeric))),
    CONSTRAINT "reimbursement_claim_items_fx_source_check" CHECK (("fx_source" = ANY (ARRAY['none'::"text", 'techcombank'::"text", 'vietcombank'::"text", 'manual'::"text", 'card'::"text"]))),
    CONSTRAINT "reimbursement_claim_items_lost_receipt_abroad" CHECK ((("lost_receipt_note" IS NULL) OR (NOT "bought_in_vietnam"))),
    CONSTRAINT "reimbursement_claim_items_other_described" CHECK ((("category" <> 'other'::"text") OR ("length"(TRIM(BOTH FROM COALESCE("description", ''::"text"))) > 0)))
);


--
-- Name: TABLE "reimbursement_claim_items"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."reimbursement_claim_items" IS 'One row is: one claim item — one receipt inside a claim: what was bought, where, when, from whom, its category, the amount in its original currency, and its value in VND. [transactional · Spend | tier 3 support | active]';


--
-- Name: COLUMN "reimbursement_claim_items"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."id" IS 'Primary key.';


--
-- Name: COLUMN "reimbursement_claim_items"."claim_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."claim_id" IS 'The claim (reimbursement_claims) the item belongs to; deleted with a deletable draft.';


--
-- Name: COLUMN "reimbursement_claim_items"."position"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."position" IS 'The item''s order within its claim.';


--
-- Name: COLUMN "reimbursement_claim_items"."description"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."description" IS 'What was bought, as the owner wrote it; required when the category is other.';


--
-- Name: COLUMN "reimbursement_claim_items"."seller"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."seller" IS 'Who sold it, as the owner or the AI reading wrote it.';


--
-- Name: COLUMN "reimbursement_claim_items"."bought_on"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."bought_on" IS 'The date of the purchase, which the VND rate is read for.';


--
-- Name: COLUMN "reimbursement_claim_items"."category"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."category" IS 'The item''s category. Valid values: [transport, flights, accommodation, meals_travel, client_entertainment, software, equipment, training_events, other]';


--
-- Name: COLUMN "reimbursement_claim_items"."bought_in_vietnam"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."bought_in_vietnam" IS 'Whether the item was bought in Vietnam, which requires a red invoice; the app defaults it to true for VND.';


--
-- Name: COLUMN "reimbursement_claim_items"."amount_cents"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."amount_cents" IS 'The amount paid in the item''s currency, in minor units (whole dong for VND, a zero-decimal currency).';


--
-- Name: COLUMN "reimbursement_claim_items"."currency"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."currency" IS 'The currency it was paid in, lowercase ISO 4217 ("vnd", "aud").';


--
-- Name: COLUMN "reimbursement_claim_items"."amount_vnd"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."amount_vnd" IS 'The item''s value in whole VND; null while no rate is known.';


--
-- Name: COLUMN "reimbursement_claim_items"."fx_rate"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."fx_rate" IS 'VND per one unit of the currency that amount_vnd was computed with; 1 for VND.';


--
-- Name: COLUMN "reimbursement_claim_items"."fx_source"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."fx_source" IS 'Where the rate came from. Valid values: [none, techcombank, vietcombank, manual, card]';


--
-- Name: COLUMN "reimbursement_claim_items"."fx_as_of"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."fx_as_of" IS 'The date the rate is for.';


--
-- Name: COLUMN "reimbursement_claim_items"."charged_vnd"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."charged_vnd" IS 'What the owner''s card actually charged in VND, when they entered it; it wins over the rate.';


--
-- Name: COLUMN "reimbursement_claim_items"."lost_receipt_note"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."lost_receipt_note" IS 'The owner''s written explanation for a receipt lost abroad; never allowed on an item bought in Vietnam.';


--
-- Name: COLUMN "reimbursement_claim_items"."ai_reading"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."ai_reading" IS 'The AI receipt reading''s structured output (amount, currency, date, seller, category, red-invoice buyer and tax code); a suggestion, never a decision.';


--
-- Name: COLUMN "reimbursement_claim_items"."ai_flags"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."ai_flags" IS 'Warnings for the checker. Valid values: [buyer_not_organisation, buyer_tax_code_differs, unreadable, possible_duplicate, older_than_90_days, not_a_red_invoice]';


--
-- Name: COLUMN "reimbursement_claim_items"."duplicate_of_item_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."duplicate_of_item_id" IS 'The earlier item (reimbursement_claim_items) this one looks like a duplicate of, when flagged.';


--
-- Name: COLUMN "reimbursement_claim_items"."declined_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."declined_at" IS 'When a checker or the approver declined this item; it stays on the claim and leaves the approved total.';


--
-- Name: COLUMN "reimbursement_claim_items"."declined_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."declined_by" IS 'The person (company_os.people) who declined it.';


--
-- Name: COLUMN "reimbursement_claim_items"."decline_reason"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."decline_reason" IS 'Why it was declined.';


--
-- Name: COLUMN "reimbursement_claim_items"."rebill"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."rebill" IS 'Whether the item is to be rebilled to a client; a tag for filtering and the export, nothing more.';


--
-- Name: COLUMN "reimbursement_claim_items"."rebill_company_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."rebill_company_id" IS 'The client (company_os.companies) to rebill, when rebill is set.';


--
-- Name: COLUMN "reimbursement_claim_items"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."created_at" IS 'When the item was added.';


--
-- Name: COLUMN "reimbursement_claim_items"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."updated_at" IS 'When the row last changed; maintained by a trigger.';


--
-- Name: COLUMN "reimbursement_claim_items"."removed_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."removed_at" IS 'When the owner took this item off a claim that had already been submitted; it stays on the claim, out of every total, because nothing ever submitted is deleted. Null while it counts.';


--
-- Name: COLUMN "reimbursement_claim_items"."removed_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."removed_by" IS 'The person (company_os.people) who took the item off.';


--
-- Name: COLUMN "reimbursement_claim_items"."remove_reason"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claim_items"."remove_reason" IS 'Why the owner took it off, in their words.';


--
-- Name: reimbursement_claims; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."reimbursement_claims" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "person_id" "uuid" NOT NULL,
    "team_member_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "trip_event_id" "uuid",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "submitted_at" timestamp with time zone,
    "checked_at" timestamp with time zone,
    "checked_by" "uuid",
    "approved_at" timestamp with time zone,
    "approved_by" "uuid",
    "approved_total_vnd" bigint,
    "in_run_at" timestamp with time zone,
    "paid_at" timestamp with time zone,
    "payment_run_id" "uuid",
    "payment_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "reimbursement_claims_approved_total_vnd_check" CHECK ((("approved_total_vnd" IS NULL) OR ("approved_total_vnd" >= 0))),
    CONSTRAINT "reimbursement_claims_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'checked'::"text", 'sent_back'::"text", 'rejected'::"text", 'approved'::"text", 'in_run'::"text", 'paid'::"text"]))),
    CONSTRAINT "reimbursement_claims_title_check" CHECK (("length"(TRIM(BOTH FROM "title")) > 0))
);


--
-- Name: TABLE "reimbursement_claims"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."reimbursement_claims" IS 'One row is: one claim — a team member''s request to be paid back for money they spent on Edge8''s behalf, moving as one thing through checking, approval and payment. [transactional · Spend | tier 3 support | active]';


--
-- Name: COLUMN "reimbursement_claims"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."id" IS 'Primary key.';


--
-- Name: COLUMN "reimbursement_claims"."person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."person_id" IS 'The person who claims and is paid back (company_os.people); their bank details are on people_sensitive.';


--
-- Name: COLUMN "reimbursement_claims"."team_member_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."team_member_id" IS 'The employment (company_os.team_members) the claim was made under, so a claim stays attributable after the person leaves.';


--
-- Name: COLUMN "reimbursement_claims"."title"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."title" IS 'The claim''s name as its owner wrote it ("Australia trip – taxis").';


--
-- Name: COLUMN "reimbursement_claims"."trip_event_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."trip_event_id" IS 'The trip the claim belongs to, an events row; null when it names none.';


--
-- Name: COLUMN "reimbursement_claims"."status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."status" IS 'Where the claim stands; changed only by the claim-lifecycle module. Valid values: [draft, submitted, checked, sent_back, rejected, approved, in_run, paid]';


--
-- Name: COLUMN "reimbursement_claims"."submitted_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."submitted_at" IS 'When the claim was last submitted; null while it was never submitted. A never-submitted draft is the only claim that may be deleted.';


--
-- Name: COLUMN "reimbursement_claims"."checked_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."checked_at" IS 'When a checker confirmed it.';


--
-- Name: COLUMN "reimbursement_claims"."checked_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."checked_by" IS 'The person (company_os.people) who checked it.';


--
-- Name: COLUMN "reimbursement_claims"."approved_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."approved_at" IS 'When it was approved; the payment run''s cut-off is read against this.';


--
-- Name: COLUMN "reimbursement_claims"."approved_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."approved_by" IS 'The person (company_os.people) who approved it.';


--
-- Name: COLUMN "reimbursement_claims"."approved_total_vnd"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."approved_total_vnd" IS 'The approved items'' total in whole VND, frozen at approval; the payment run reads it and never recomputes it.';


--
-- Name: COLUMN "reimbursement_claims"."in_run_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."in_run_at" IS 'When a payment run took the claim.';


--
-- Name: COLUMN "reimbursement_claims"."paid_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."paid_at" IS 'When the payment covering it was recorded.';


--
-- Name: COLUMN "reimbursement_claims"."payment_run_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."payment_run_id" IS 'The payment run (reimbursement_payment_runs) that took the claim; null until then.';


--
-- Name: COLUMN "reimbursement_claims"."payment_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."payment_id" IS 'The reimbursement payment (reimbursement_payments) that paid it; null until then.';


--
-- Name: COLUMN "reimbursement_claims"."metadata"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."metadata" IS 'Flow detail worth keeping with the claim that has no column of its own.';


--
-- Name: COLUMN "reimbursement_claims"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."created_at" IS 'When the claim was started.';


--
-- Name: COLUMN "reimbursement_claims"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_claims"."updated_at" IS 'When the row last changed; maintained by a trigger.';


--
-- Name: reimbursement_files; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."reimbursement_files" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "kind" "text" NOT NULL,
    "claim_item_id" "uuid",
    "payment_id" "uuid",
    "storage_path" "text" NOT NULL,
    "filename" "text" NOT NULL,
    "mime_type" "text",
    "size_bytes" bigint,
    "sha256" "text",
    "page_count" integer,
    "uploaded_by" "uuid",
    "confirmed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "replaced_at" timestamp with time zone,
    "replaced_by" "uuid",
    CONSTRAINT "reimbursement_files_kind_check" CHECK (("kind" = ANY (ARRAY['receipt'::"text", 'red_invoice'::"text", 'bank_receipt'::"text", 'bank_deduction'::"text"]))),
    CONSTRAINT "reimbursement_files_owner_shape" CHECK (((("kind" = 'bank_receipt'::"text") AND ("payment_id" IS NOT NULL) AND ("claim_item_id" IS NULL)) OR (("kind" <> 'bank_receipt'::"text") AND ("claim_item_id" IS NOT NULL) AND ("payment_id" IS NULL)))),
    CONSTRAINT "reimbursement_files_page_count_check" CHECK ((("page_count" IS NULL) OR ("page_count" > 0))),
    CONSTRAINT "reimbursement_files_sha256_check" CHECK ((("sha256" IS NULL) OR ("sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "reimbursement_files_size_bytes_check" CHECK ((("size_bytes" IS NULL) OR ("size_bytes" >= 0)))
);


--
-- Name: TABLE "reimbursement_files"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."reimbursement_files" IS 'One row is: one stored document — a receipt or red invoice on a claim item, or a bank receipt on a reimbursement payment — in the private reimbursement-receipts bucket. [transactional · Spend | tier 3 support | active]';


--
-- Name: COLUMN "reimbursement_files"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."id" IS 'Primary key.';


--
-- Name: COLUMN "reimbursement_files"."kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."kind" IS 'What the document is. Valid values: [receipt, red_invoice, bank_receipt, bank_deduction]';


--
-- Name: COLUMN "reimbursement_files"."claim_item_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."claim_item_id" IS 'The claim item (reimbursement_claim_items) a receipt or red invoice belongs to; null for a bank receipt.';


--
-- Name: COLUMN "reimbursement_files"."payment_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."payment_id" IS 'The reimbursement payment (reimbursement_payments) a bank receipt belongs to; null otherwise.';


--
-- Name: COLUMN "reimbursement_files"."storage_path"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."storage_path" IS 'The object''s path in the reimbursement-receipts bucket; unique.';


--
-- Name: COLUMN "reimbursement_files"."filename"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."filename" IS 'The name it was uploaded with, as people see it.';


--
-- Name: COLUMN "reimbursement_files"."mime_type"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."mime_type" IS 'The MIME type the server read from the stored object on confirm.';


--
-- Name: COLUMN "reimbursement_files"."size_bytes"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."size_bytes" IS 'The stored object''s size in bytes as the server read it on confirm.';


--
-- Name: COLUMN "reimbursement_files"."sha256"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."sha256" IS 'The object''s SHA-256, for duplicate detection.';


--
-- Name: COLUMN "reimbursement_files"."page_count"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."page_count" IS 'For a PDF, its number of pages, when known.';


--
-- Name: COLUMN "reimbursement_files"."uploaded_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."uploaded_by" IS 'The person (company_os.people) who uploaded it.';


--
-- Name: COLUMN "reimbursement_files"."confirmed_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."confirmed_at" IS 'When the server confirmed the stored object; null while an upload is unfinished, and such rows are never shown.';


--
-- Name: COLUMN "reimbursement_files"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."created_at" IS 'When the row was inserted, which is when its upload started.';


--
-- Name: COLUMN "reimbursement_files"."replaced_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."replaced_at" IS 'When the owner set this receipt or red invoice aside in favour of another on a claim that had already been submitted; it stays, shown as replaced, because nothing ever submitted is deleted. Null while it is current.';


--
-- Name: COLUMN "reimbursement_files"."replaced_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_files"."replaced_by" IS 'The person (company_os.people) who set it aside.';


--
-- Name: reimbursement_fx_rates; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."reimbursement_fx_rates" (
    "rate_date" "date" NOT NULL,
    "currency" "text" NOT NULL,
    "source" "text" NOT NULL,
    "rate_vnd" numeric NOT NULL,
    "fetched_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "entered_by" "uuid",
    CONSTRAINT "reimbursement_fx_rates_currency_check" CHECK (("currency" ~ '^[a-z]{3}$'::"text")),
    CONSTRAINT "reimbursement_fx_rates_rate_vnd_check" CHECK (("rate_vnd" > (0)::numeric)),
    CONSTRAINT "reimbursement_fx_rates_source_check" CHECK (("source" = ANY (ARRAY['techcombank'::"text", 'vietcombank'::"text", 'manual'::"text"])))
);


--
-- Name: TABLE "reimbursement_fx_rates"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."reimbursement_fx_rates" IS 'One row is: one day''s selling rate of one currency in VND from one source, used to value claim items bought abroad. [master · Reference & rules | tier 3 support | active]';


--
-- Name: COLUMN "reimbursement_fx_rates"."rate_date"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_fx_rates"."rate_date" IS 'The day the rate is for.';


--
-- Name: COLUMN "reimbursement_fx_rates"."currency"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_fx_rates"."currency" IS 'The currency, lowercase ISO 4217.';


--
-- Name: COLUMN "reimbursement_fx_rates"."source"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_fx_rates"."source" IS 'Who published the rate. Valid values: [techcombank, vietcombank, manual]';


--
-- Name: COLUMN "reimbursement_fx_rates"."rate_vnd"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_fx_rates"."rate_vnd" IS 'VND per one unit of the currency (the bank''s selling rate).';


--
-- Name: COLUMN "reimbursement_fx_rates"."fetched_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_fx_rates"."fetched_at" IS 'When the rate was fetched or entered.';


--
-- Name: COLUMN "reimbursement_fx_rates"."entered_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_fx_rates"."entered_by" IS 'The person (company_os.people) who entered a manual rate; null for a fetched one.';


--
-- Name: reimbursement_payment_runs; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."reimbursement_payment_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "run_date" "date" NOT NULL,
    "cutoff_at" timestamp with time zone NOT NULL,
    "built_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "claims_count" integer DEFAULT 0 NOT NULL,
    "people_count" integer DEFAULT 0 NOT NULL,
    "total_vnd" bigint DEFAULT 0 NOT NULL,
    "notified_at" timestamp with time zone,
    "paid_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "reimbursement_payment_runs_claims_count_check" CHECK (("claims_count" >= 0)),
    CONSTRAINT "reimbursement_payment_runs_people_count_check" CHECK (("people_count" >= 0)),
    CONSTRAINT "reimbursement_payment_runs_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'paid'::"text"]))),
    CONSTRAINT "reimbursement_payment_runs_total_vnd_check" CHECK (("total_vnd" >= 0))
);


--
-- Name: TABLE "reimbursement_payment_runs"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."reimbursement_payment_runs" IS 'One row is: one payment run — the list of everyone to pay back, built at 08:00 Vietnam time on the 1st or the 15th from the claims approved before its cut-off. [transactional · Spend | tier 3 support | active]';


--
-- Name: COLUMN "reimbursement_payment_runs"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."id" IS 'Primary key.';


--
-- Name: COLUMN "reimbursement_payment_runs"."run_date"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."run_date" IS 'The day the run is for, the 1st or the 15th; unique, the idempotency key.';


--
-- Name: COLUMN "reimbursement_payment_runs"."cutoff_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."cutoff_at" IS '00:00 Asia/Ho_Chi_Minh on run_date; claims approved before it are in the run.';


--
-- Name: COLUMN "reimbursement_payment_runs"."built_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."built_at" IS 'When the run was built.';


--
-- Name: COLUMN "reimbursement_payment_runs"."status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."status" IS 'Where the run stands. Valid values: [open, paid]';


--
-- Name: COLUMN "reimbursement_payment_runs"."claims_count"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."claims_count" IS 'How many claims the run took.';


--
-- Name: COLUMN "reimbursement_payment_runs"."people_count"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."people_count" IS 'How many people it pays.';


--
-- Name: COLUMN "reimbursement_payment_runs"."total_vnd"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."total_vnd" IS 'What it pays in total, in whole VND.';


--
-- Name: COLUMN "reimbursement_payment_runs"."notified_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."notified_at" IS 'When the run-built notice went to accounting@ and the Lark Operations chat; null until then.';


--
-- Name: COLUMN "reimbursement_payment_runs"."paid_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."paid_at" IS 'When the last payment in it was recorded.';


--
-- Name: COLUMN "reimbursement_payment_runs"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payment_runs"."created_at" IS 'When the row was inserted.';


--
-- Name: reimbursement_payments; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."reimbursement_payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "run_id" "uuid" NOT NULL,
    "person_id" "uuid" NOT NULL,
    "amount_vnd" bigint NOT NULL,
    "paid_vnd" bigint,
    "status" "text" DEFAULT 'to_pay'::"text" NOT NULL,
    "paid_at" timestamp with time zone,
    "paid_by" "uuid",
    "bank_receipt_file_id" "uuid",
    "bank_name_snapshot" "text",
    "bank_account_last4" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "reimbursement_payments_amount_vnd_check" CHECK (("amount_vnd" >= 0)),
    CONSTRAINT "reimbursement_payments_bank_account_last4_check" CHECK ((("bank_account_last4" IS NULL) OR ("bank_account_last4" ~ '^[0-9]{1,4}$'::"text"))),
    CONSTRAINT "reimbursement_payments_paid_shape" CHECK (((("status" = 'paid'::"text") AND ("paid_at" IS NOT NULL) AND ("paid_vnd" IS NOT NULL) AND ("bank_receipt_file_id" IS NOT NULL)) OR (("status" = 'to_pay'::"text") AND ("paid_at" IS NULL)))),
    CONSTRAINT "reimbursement_payments_paid_vnd_check" CHECK ((("paid_vnd" IS NULL) OR ("paid_vnd" >= 0))),
    CONSTRAINT "reimbursement_payments_status_check" CHECK (("status" = ANY (ARRAY['to_pay'::"text", 'paid'::"text"])))
);


--
-- Name: TABLE "reimbursement_payments"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."reimbursement_payments" IS 'One row is: one reimbursement payment — one bank transfer that pays one person for their claims in one run, recorded with the bank''s receipt and the VND actually sent. [transactional · Spend | tier 3 support | active]';


