COMMENT ON COLUMN "company_os"."reimbursement_payments"."status" IS 'Where it stands. Valid values: [to_pay, paid]';


--
-- Name: COLUMN "reimbursement_payments"."paid_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payments"."paid_at" IS 'When it was recorded paid.';


--
-- Name: COLUMN "reimbursement_payments"."paid_by"; Type: COMMENT; Schema: company_os; Owner: -
