--
-- Name: COLUMN "reimbursement_payments"."bank_receipt_file_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."reimbursement_payments"."bank_receipt_file_id" IS 'The bank''s receipt for the transfer (reimbursement_files).';


