--

COMMENT ON COLUMN "company_os"."reimbursement_payments"."created_at" IS 'When the row was inserted.';


--
-- Name: renewals; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."renewals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "renews_on" "date" NOT NULL,
    "term_months" integer,
    "status" "text" DEFAULT 'upcoming'::"text" NOT NULL,
    "note" "text",
    "archived_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "renewals_status_check" CHECK (("status" = ANY (ARRAY['upcoming'::"text", 'renewed'::"text", 'churned'::"text", 'lapsed'::"text"]))),
    CONSTRAINT "renewals_term_months_check" CHECK (("term_months" > 0))
);


--
-- Name: TABLE "renewals"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."renewals" IS 'One row is: one renewal date of one client account — when its current agreement comes up for renewal, and how that renewal went. [transactional · Revenue documents | tier 3 support | active]';


--
-- Name: COLUMN "renewals"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."renewals"."id" IS 'Primary key.';


--
-- Name: COLUMN "renewals"."company_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."renewals"."company_id" IS 'The client account, referencing companies.id; deleting the company deletes its renewals.';


--
-- Name: COLUMN "renewals"."renews_on"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."renewals"."renews_on" IS 'The day the current agreement comes up for renewal.';


