--
-- Name: routine_config; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."routine_config" (
    "routine_id" "text" NOT NULL,
    "mode" "text" DEFAULT 'live'::"text" NOT NULL,
    "paused_reason" "text",
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "routine_config_mode_check" CHECK (("mode" = ANY (ARRAY['live'::"text", 'paused'::"text", 'shadow'::"text"]))),
    CONSTRAINT "routine_config_paused_says_why" CHECK ((("mode" <> 'paused'::"text") OR ("length"("btrim"(COALESCE("paused_reason", ''::"text"))) > 0)))
);


--
-- Name: TABLE "routine_config"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."routine_config" IS 'One row is: one scheduled routine''s switch — live, shadow or paused, and why it was paused; a routine with no row is live. [other · System config & plumbing | tier 3 support | active]';


--
-- Name: COLUMN "routine_config"."routine_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_config"."routine_id" IS 'The routine''s id, the cron path vercel.json schedules it on (e.g. /api/cron/payment-run/); the same string routine_runs.routine_id holds.';


--
-- Name: COLUMN "routine_config"."mode"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_config"."mode" IS 'Valid values: [live, paused, shadow]. paused makes withRoutineRun record a skipped run naming paused_reason instead of doing the work; shadow runs the work as a routine_runs row with mode shadow and records each outward effect in automation_effects instead of acting (Z.17).';


--
-- Name: COLUMN "routine_config"."paused_reason"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_config"."paused_reason" IS 'Why the routine is paused, in a sentence; required while mode is paused, and copied into each skipped run''s reason.';


--
-- Name: COLUMN "routine_config"."updated_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_config"."updated_by" IS 'The person who last set the switch; null when set by a migration or a script.';


--
-- Name: COLUMN "routine_config"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_config"."updated_at" IS 'When the switch was last set.';


--
-- Name: routine_runs; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."routine_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "routine_id" "text" NOT NULL,
    "host" "text" NOT NULL,
    "status" "text" DEFAULT 'running'::"text" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finished_at" timestamp with time zone,
    "duration_ms" integer,
    "summary" "text",
    "result" "jsonb",
    "error" "text",
    "log" "text",
    "ai_calls" integer DEFAULT 0 NOT NULL,
    "ai_input_tokens" bigint DEFAULT 0 NOT NULL,
    "ai_output_tokens" bigint DEFAULT 0 NOT NULL,
    "ai_cache_read_tokens" bigint DEFAULT 0 NOT NULL,
    "ai_cache_write_tokens" bigint DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tick_key" "text",
    "mode" "text" DEFAULT 'live'::"text" NOT NULL,
    "attempt" integer DEFAULT 1 NOT NULL,
    "workflow_run_id" "text",
    "step_deadline_at" timestamp with time zone,
    CONSTRAINT "routine_runs_host_check" CHECK (("host" = ANY (ARRAY['vercel'::"text", 'mac-mini'::"text"]))),
    CONSTRAINT "routine_runs_mode_check" CHECK (("mode" = ANY (ARRAY['shadow'::"text", 'live'::"text"]))),
    CONSTRAINT "routine_runs_status_check" CHECK (("status" = ANY (ARRAY['running'::"text", 'waiting'::"text", 'ok'::"text", 'skipped'::"text", 'error'::"text", 'died'::"text"])))
);


--
-- Name: TABLE "routine_runs"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."routine_runs" IS 'one execution of one scheduled routine (a Vercel cron or a Mac mini launchd job) with its outcome, result and AI token usage.';


--
-- Name: COLUMN "routine_runs"."routine_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."routine_id" IS 'Stable routine key: the cron path for Vercel routines (e.g. /api/cron/probation-reviews/) or mac-mini:<job> for launchd jobs.';


--
-- Name: COLUMN "routine_runs"."host"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."host" IS 'Where the run executed. Valid values: [vercel, mac-mini]';


--
-- Name: COLUMN "routine_runs"."status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."status" IS 'Run outcome. running from the claim until the run closes its row; waiting while parked on an approval or a delayed send (never reaped); died when the reaper found a running row past its step deadline. Valid values: [running, waiting, ok, skipped, error, died]';


--
-- Name: COLUMN "routine_runs"."started_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."started_at" IS 'When the run began.';


--
-- Name: COLUMN "routine_runs"."finished_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."finished_at" IS 'When the run ended; null while running or if the process died.';


--
-- Name: COLUMN "routine_runs"."duration_ms"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."duration_ms" IS 'finished_at minus started_at in milliseconds.';


--
-- Name: COLUMN "routine_runs"."summary"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."summary" IS 'One human line describing what the run did, derived from its result.';


--
-- Name: COLUMN "routine_runs"."result"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."result" IS 'The JSON body the routine returned (its own counters and notes).';


--
-- Name: COLUMN "routine_runs"."error"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."error" IS 'Error message when status is error.';


--
-- Name: COLUMN "routine_runs"."log"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."log" IS 'Captured log lines for the run, newline separated (Mac mini jobs paste their output here).';


--
-- Name: COLUMN "routine_runs"."ai_calls"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."ai_calls" IS 'Number of model calls made during the run.';


--
-- Name: COLUMN "routine_runs"."ai_input_tokens"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."ai_input_tokens" IS 'Sum of input tokens across the run''s model calls.';


--
-- Name: COLUMN "routine_runs"."ai_output_tokens"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."ai_output_tokens" IS 'Sum of output tokens across the run''s model calls.';


--
-- Name: COLUMN "routine_runs"."ai_cache_read_tokens"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."ai_cache_read_tokens" IS 'Sum of prompt-cache read tokens across the run''s model calls.';


--
-- Name: COLUMN "routine_runs"."ai_cache_write_tokens"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."ai_cache_write_tokens" IS 'Sum of prompt-cache write tokens across the run''s model calls.';


--
-- Name: COLUMN "routine_runs"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."created_at" IS 'Row insert time.';


--
-- Name: COLUMN "routine_runs"."tick_key"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."tick_key" IS 'The schedule slot, event id or button UUID this run belongs to; with routine_id and mode it is unique among live outcomes. Null on rows written before 2026-09-28.';


--
-- Name: COLUMN "routine_runs"."mode"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."mode" IS 'Whether the run acted (live) or only recorded what it would do (shadow). Valid values: [shadow, live]';


--
-- Name: COLUMN "routine_runs"."attempt"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."attempt" IS 'Which attempt at this tick the row is; a retry of an errored or died tick is a new row with attempt + 1.';


--
-- Name: COLUMN "routine_runs"."workflow_run_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."workflow_run_id" IS 'The durable workflow runtime''s run id; null on a plain cron.';


--
-- Name: COLUMN "routine_runs"."step_deadline_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."routine_runs"."step_deadline_at" IS 'Heartbeat: when the current step must have finished. The reaper marks a running row died 60 seconds after it passes.';


