-- Name: COLUMN "social_post_metrics"."posted_on"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."social_post_metrics"."posted_on" IS 'The day the post was published, as the platform reports it.';


