--
-- Name: COLUMN "survey_assignments"."assigned_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."survey_assignments"."assigned_by" IS 'Email of the admin who assigned it.';


