-- Name: COLUMN "survey_assignments"."completed_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."survey_assignments"."completed_at" IS 'When the person submitted a response; null while it is open.';


