--
-- Name: task_attachments; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."task_attachments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "task_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "storage_path" "text",
    "filename" "text",
    "mime_type" "text",
    "size_bytes" bigint,
    "width" integer,
    "height" integer,
    "url" "text",
    "title" "text",
    "uploaded_by" "uuid",
    "confirmed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    "archived_by" "uuid",
    CONSTRAINT "task_attachments_height_check" CHECK ((("height" IS NULL) OR ("height" > 0))),
    CONSTRAINT "task_attachments_kind_check" CHECK (("kind" = ANY (ARRAY['file'::"text", 'link'::"text"]))),
    CONSTRAINT "task_attachments_kind_shape" CHECK (((("kind" = 'file'::"text") AND ("storage_path" IS NOT NULL) AND ("filename" IS NOT NULL) AND ("url" IS NULL)) OR (("kind" = 'link'::"text") AND ("url" IS NOT NULL) AND ("storage_path" IS NULL) AND ("filename" IS NULL) AND ("confirmed_at" IS NOT NULL)))),
    CONSTRAINT "task_attachments_size_bytes_check" CHECK ((("size_bytes" IS NULL) OR ("size_bytes" >= 0))),
    CONSTRAINT "task_attachments_url_check" CHECK ((("url" IS NULL) OR ("url" ~* '^https?://'::"text"))),
    CONSTRAINT "task_attachments_width_check" CHECK ((("width" IS NULL) OR ("width" > 0)))
);


--
-- Name: TABLE "task_attachments"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."task_attachments" IS 'One row is: one deliverable on one card — a file in the private card-attachments bucket, or a link — what the card''s work produced, other than its PR. [transactional · Client delivery & work | tier 3 support | active]';


--
-- Name: COLUMN "task_attachments"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."id" IS 'Primary key.';


--
-- Name: COLUMN "task_attachments"."task_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."task_id" IS 'The card (company_os.tasks) the deliverable belongs to; the row is deleted with its card.';


--
-- Name: COLUMN "task_attachments"."kind"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."kind" IS 'Whether the deliverable is a stored file or a link. Valid values: [file, link]';


--
-- Name: COLUMN "task_attachments"."storage_path"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."storage_path" IS 'For a file, the object''s path in the card-attachments bucket (task/<task id>/<random id>-<name>); unique. Null for a link.';


--
-- Name: COLUMN "task_attachments"."filename"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."filename" IS 'For a file, the name it was uploaded with, as people see it. Null for a link.';


--
-- Name: COLUMN "task_attachments"."mime_type"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."mime_type" IS 'For a file, the MIME type the server read from the stored object on confirm. Null for a link.';


--
-- Name: COLUMN "task_attachments"."size_bytes"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."size_bytes" IS 'For a file, the stored object''s size in bytes as the server read it on confirm. Null for a link.';


--
-- Name: COLUMN "task_attachments"."width"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."width" IS 'For an image, its width in pixels, when known. Null otherwise.';


--
-- Name: COLUMN "task_attachments"."height"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."height" IS 'For an image, its height in pixels, when known. Null otherwise.';


--
-- Name: COLUMN "task_attachments"."url"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."url" IS 'For a link, its address; http or https only. Null for a file.';


--
-- Name: COLUMN "task_attachments"."title"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."title" IS 'For a link, the words shown for it; for a file, an optional caption. Null when there is none.';


--
-- Name: COLUMN "task_attachments"."uploaded_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."uploaded_by" IS 'The person (company_os.people) who added the deliverable; null when the adder has no person record or that person was removed.';


--
-- Name: COLUMN "task_attachments"."confirmed_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."confirmed_at" IS 'When the deliverable became real: a file once the server confirmed the stored object, a link when it was added. Null while an upload is unfinished; unconfirmed rows are never shown.';


--
-- Name: COLUMN "task_attachments"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."created_at" IS 'When the row was inserted (for a file, when its upload started).';


--
-- Name: COLUMN "task_attachments"."archived_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."archived_at" IS 'When the deliverable was removed from the card. Null while it is live; the sweep purges an archived file''s object after 30 days.';


--
-- Name: COLUMN "task_attachments"."archived_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_attachments"."archived_by" IS 'The person (company_os.people) who removed it; null while it is live.';


--
-- Name: task_comments; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."task_comments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "task_id" "uuid" NOT NULL,
    "author_person_id" "uuid",
    "author_label" "text" NOT NULL,
    "body" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "parent_comment_id" "uuid",
    "resolved_at" timestamp with time zone,
    "resolved_by_person_id" "uuid",
    "resolved_by_label" "text",
    "mentions" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL
);


--
-- Name: COLUMN "task_comments"."parent_comment_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_comments"."parent_comment_id" IS 'The top-level comment this one replies to; null for a top-level comment. One level only: a reply is never a parent.';


--
-- Name: COLUMN "task_comments"."resolved_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_comments"."resolved_at" IS 'When the thread this top-level comment starts was resolved; null while it is open. Replies are never resolved on their own.';


--
-- Name: COLUMN "task_comments"."resolved_by_person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_comments"."resolved_by_person_id" IS 'FK to people; who resolved the thread, when they have a people row.';


--
-- Name: COLUMN "task_comments"."resolved_by_label"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_comments"."resolved_by_label" IS 'The display name (or admin email) of whoever resolved the thread, stored so the line always names someone.';


--
-- Name: COLUMN "task_comments"."mentions"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."task_comments"."mentions" IS 'Person ids the comment @mentioned, stored at write time; each was notified once, when the comment was written.';


--
-- Name: task_stage_log; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."task_stage_log" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "task_id" "uuid" NOT NULL,
    "from_column_id" "uuid",
    "to_column_id" "uuid",
    "from_sprint_id" "uuid",
    "to_sprint_id" "uuid",
    "kind" "text" DEFAULT 'move'::"text" NOT NULL,
    "moved_by" "uuid",
    "note" "text",
    "moved_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: tasks; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."tasks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "board_id" "uuid",
    "board_column_id" "uuid",
    "sprint_id" "uuid",
    "position" double precision DEFAULT 0 NOT NULL,
    "assignee_id" "uuid",
    "created_by" "uuid",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "priority" "text" DEFAULT 'p3'::"text" NOT NULL,
    "due_date" "date",
    "completed_at" timestamp with time zone,
    "internal" boolean DEFAULT false NOT NULL,
    "subject_type" "text",
    "subject_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "archived_at" timestamp with time zone,
    "archived_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "parent_task_id" "uuid",
    "human_tokens" numeric(6,2),
    "epic_id" "uuid"
);


--
-- Name: COLUMN "tasks"."status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."tasks"."status" IS 'Whether the card is open, finished, or closed without being done; moving into a done column sets done, into a Not Doing column sets not_doing. Valid values: [open, done, not_doing].';


--
-- Name: COLUMN "tasks"."subject_type"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."tasks"."subject_type" IS 'Polymorphic link slot - one link per card: a coaching commitment, a client roadmap item or a contractor work request, never two. Valid values: [coaching_commitment, client_backlog_item, contractor_work_request].';


--
-- Name: COLUMN "tasks"."human_tokens"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."tasks"."human_tokens" IS 'Human-token estimate of effort for the card (and each subtask), read from the shape of the work on a 0.05 grid with no ceiling; never a forecast of time or resources. Scale: .claude/skills/workboard-cards/SKILL.md.';


--
-- Name: COLUMN "tasks"."epic_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."tasks"."epic_id" IS 'FK to epics (on delete set null); the epic this card is grouped under, or null.';


--
-- Name: time_off; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."time_off" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "team_member_id" "uuid" NOT NULL,
    "leave_type" "text" DEFAULT 'vacation'::"text" NOT NULL,
    "status" "text" DEFAULT 'requested'::"text" NOT NULL,
    "start_date" "date" NOT NULL,
    "end_date" "date" NOT NULL,
    "is_half_day" boolean DEFAULT false NOT NULL,
    "hours" numeric(5,2),
    "reason" "text",
    "approved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "external_source" "text",
    "external_id" "text",
    "days" numeric,
    "manager_note" "text",
    "requested_at" timestamp with time zone,
    CONSTRAINT "time_off_check" CHECK (("end_date" >= "start_date")),
    CONSTRAINT "time_off_leave_type_check" CHECK (("leave_type" = ANY (ARRAY['vacation'::"text", 'sick'::"text", 'personal'::"text", 'parental'::"text", 'bereavement'::"text", 'unpaid'::"text", 'public_holiday'::"text", 'other'::"text"]))),
    CONSTRAINT "time_off_status_check" CHECK (("status" = ANY (ARRAY['requested'::"text", 'approved'::"text", 'rejected'::"text", 'cancelled'::"text", 'taken'::"text"])))
);


--
-- Name: token_purchases; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."token_purchases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "person_id" "uuid" NOT NULL,
    "order_id" "uuid",
    "packs" integer NOT NULL,
    "tokens" integer NOT NULL,
    "amount_cents" bigint NOT NULL,
    "currency" "text" DEFAULT 'usd'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "stripe_session_id" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "paid_at" timestamp with time zone,
    CONSTRAINT "token_purchases_packs_check" CHECK ((("packs" >= 1) AND ("packs" <= 4))),
    CONSTRAINT "token_purchases_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'paid'::"text", 'expired'::"text"])))
);


--
-- Name: training_assignments; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."training_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "training_id" "uuid" NOT NULL,
    "due_at" timestamp with time zone NOT NULL,
    "prompt" "text" NOT NULL,
    "accepts" "text"[] DEFAULT '{written,upload,link,recording}'::"text"[] NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "training_assignments_accepts_check" CHECK ((("cardinality"("accepts") > 0) AND ("accepts" <@ ARRAY['written'::"text", 'upload'::"text", 'link'::"text", 'recording'::"text"]))),
    CONSTRAINT "training_assignments_prompt_check" CHECK (("length"(TRIM(BOTH FROM "prompt")) > 0))
);


--
