--
-- Name: training_attendance; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."training_attendance" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "training_id" "uuid" NOT NULL,
    "person_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "skip_reason" "text",
    "answered_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "removed_at" timestamp with time zone,
    "removed_by" "uuid",
    "source" "text" DEFAULT 'member'::"text" NOT NULL,
    CONSTRAINT "training_attendance_answered_shape" CHECK ((("status" = 'pending'::"text") = ("answered_at" IS NULL))),
    CONSTRAINT "training_attendance_reason_only_when_skipped" CHECK ((("skip_reason" IS NULL) OR ("status" = 'skipped'::"text"))),
    CONSTRAINT "training_attendance_skip_reason_check" CHECK (("skip_reason" = ANY (ARRAY['clashed'::"text", 'unwell'::"text", 'needed_rest'::"text", 'other'::"text"]))),
    CONSTRAINT "training_attendance_source_check" CHECK (("source" = ANY (ARRAY['member'::"text", 'transcript'::"text", 'organiser'::"text"]))),
    CONSTRAINT "training_attendance_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'attended'::"text", 'skipped'::"text", 'absent'::"text"])))
);


--
-- Name: TABLE "training_attendance"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."training_attendance" IS 'One row is: one person on one training, with that person''s own word on whether they went. Never read about one person for someone else (ADR 0016). [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "training_attendance"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."id" IS 'Primary key.';


--
-- Name: COLUMN "training_attendance"."training_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."training_id" IS 'The training (trainings).';


--
-- Name: COLUMN "training_attendance"."person_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."person_id" IS 'The person (company_os.people) on it.';


--
-- Name: COLUMN "training_attendance"."status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."status" IS 'The member''s word: pending until they answer, or, on a taught session, what the transcript said (absent when it did not hear them) until they or the organiser correct it. Valid values: [pending, attended, skipped, absent]';


--
-- Name: COLUMN "training_attendance"."skip_reason"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."skip_reason" IS 'Why they skipped, if they chose to say; only on a skip. Valid values: [clashed, unwell, needed_rest, other]';


--
-- Name: COLUMN "training_attendance"."answered_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."answered_at" IS 'When the member answered; null while pending.';


--
-- Name: COLUMN "training_attendance"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."created_at" IS 'When the person was put on the training.';


--
-- Name: COLUMN "training_attendance"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."updated_at" IS 'When the row last changed.';


--
-- Name: COLUMN "training_attendance"."removed_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."removed_at" IS 'When the organiser took the person off, before the training started; never deleted.';


--
-- Name: COLUMN "training_attendance"."removed_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."removed_by" IS 'The person (company_os.people) who took them off.';


--
-- Name: COLUMN "training_attendance"."source"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_attendance"."source" IS 'Who set the status: member (their own word, the default), transcript (the session''s recording said who spoke), organiser (the teacher corrected it). An override by the member or the organiser is never overwritten by a later transcript (ADR 0016, amended for taught sessions). Valid values: [member, transcript, organiser]';


--
-- Name: training_exercises; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."training_exercises" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "side" "text" NOT NULL,
    "skills" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "format" "text",
    "minutes_min" integer NOT NULL,
    "minutes_max" integer NOT NULL,
    "instructions" "text",
    "materials_url" "text",
    "homework_able" boolean DEFAULT false NOT NULL,
    "created_by" "uuid",
    "plan_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    "archived_by" "uuid",
    CONSTRAINT "training_exercises_format_check" CHECK ((("format" IS NULL) OR ("length"(TRIM(BOTH FROM "format")) > 0))),
    CONSTRAINT "training_exercises_materials_url_check" CHECK ((("materials_url" IS NULL) OR ("length"(TRIM(BOTH FROM "materials_url")) > 0))),
    CONSTRAINT "training_exercises_minutes_min_check" CHECK (("minutes_min" > 0)),
    CONSTRAINT "training_exercises_minutes_range" CHECK (("minutes_max" >= "minutes_min")),
    CONSTRAINT "training_exercises_side_check" CHECK (("side" = ANY (ARRAY['presentation'::"text", 'reactive'::"text"]))),
    CONSTRAINT "training_exercises_title_check" CHECK (("length"(TRIM(BOTH FROM "title")) > 0))
);


--
