    "title" "text" NOT NULL,
    "organiser_id" "uuid" NOT NULL,
    "rhythm" "jsonb" NOT NULL,
    "published_until" "date",
    "lark_title" "text",
    "recipients" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "philosophy" "jsonb",
    "philosophy_updated_at" timestamp with time zone,
    "philosophy_updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    "archived_by" "uuid",
    CONSTRAINT "training_plans_lark_title_check" CHECK ((("lark_title" IS NULL) OR ("length"(TRIM(BOTH FROM "lark_title")) > 0))),
    CONSTRAINT "training_plans_philosophy_check" CHECK ((("philosophy" IS NULL) OR ("jsonb_typeof"("philosophy") = 'object'::"text"))),
    CONSTRAINT "training_plans_philosophy_shape" CHECK ((("philosophy" IS NULL) = ("philosophy_updated_at" IS NULL))),
    CONSTRAINT "training_plans_recipients_check" CHECK (("jsonb_typeof"("recipients") = 'array'::"text")),
    CONSTRAINT "training_plans_rhythm_check" CHECK (("jsonb_typeof"("rhythm") = 'object'::"text")),
    CONSTRAINT "training_plans_title_check" CHECK (("length"(TRIM(BOTH FROM "title")) > 0))
);


--
-- Name: TABLE "training_plans"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."training_plans" IS 'One row is: one series of trainings an organiser runs on a rhythm — an English class on Tuesdays and Thursdays, a weekly 1-1, a scrim block — published as trainings up to a date, with the programme philosophy its prep drafts and recaps read. [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "training_plans"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."id" IS 'Primary key.';


--
-- Name: COLUMN "training_plans"."type_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."type_id" IS 'The kind of training every occurrence of this plan is (training_types).';


--
-- Name: COLUMN "training_plans"."title"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."title" IS 'What the plan is called, as its members see it; each published training takes it as its title.';


--
-- Name: COLUMN "training_plans"."organiser_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."organiser_id" IS 'The person (company_os.people) who runs the plan: the teacher or coach. Only they publish, extend or change it.';


--
-- Name: COLUMN "training_plans"."rhythm"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."rhythm" IS 'When it meets: {weekdays: [2, 4], start: "14:00", end: "15:15", tz: "Asia/Ho_Chi_Minh"}; weekdays are ISO numbers, Monday 1 to Sunday 7, in the plan''s zone.';


--
-- Name: COLUMN "training_plans"."published_until"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."published_until" IS 'The last date trainings have been created up to; null until the organiser first publishes. Nothing but the organiser extends it.';


--
-- Name: COLUMN "training_plans"."lark_title"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."lark_title" IS 'The title of the Lark meeting the plan''s sessions are recorded under, which the pickup matches recordings by; null when sessions are not recorded.';


--
-- Name: COLUMN "training_plans"."recipients"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."recipients" IS 'Who receives the plan''s weekly recap email: an array of {person_id, email}, the person (company_os.people) and the address of theirs the recap goes to, since a person may have more than one row. Empty when no recap is sent.';


--
-- Name: COLUMN "training_plans"."philosophy"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."philosophy" IS 'The programme brief every prep draft and recap reads and the members see: {purpose, halves: {presentation, reactive, split}, group_for, one_on_one_for, pressure_rule, homework_rule, good_looks_like: [{line, side}], source}; null until seeded.';


--
-- Name: COLUMN "training_plans"."philosophy_updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."philosophy_updated_at" IS 'When the philosophy was last written; null while it is null.';


--
-- Name: COLUMN "training_plans"."philosophy_updated_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."philosophy_updated_by" IS 'The person (company_os.people) who last wrote the philosophy.';


--
-- Name: COLUMN "training_plans"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."created_at" IS 'When the plan was created.';


--
-- Name: COLUMN "training_plans"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."updated_at" IS 'When the row last changed.';


--
-- Name: COLUMN "training_plans"."archived_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."archived_at" IS 'When the organiser retired the plan; its trainings keep it, nothing new is published from it.';


--
-- Name: COLUMN "training_plans"."archived_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_plans"."archived_by" IS 'The person (company_os.people) who retired it.';


--
-- Name: training_reviews; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."training_reviews" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "attendance_id" "uuid" NOT NULL,
    "attendance_status" "text" DEFAULT 'attended'::"text" NOT NULL,
    "stars" smallint NOT NULL,
    "load" "text",
    "tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "note" "text",
    "signed" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "training_reviews_attendance_status_check" CHECK (("attendance_status" = 'attended'::"text")),
    CONSTRAINT "training_reviews_load_check" CHECK (("load" = ANY (ARRAY['too_little'::"text", 'about_right'::"text", 'too_much'::"text"]))),
    CONSTRAINT "training_reviews_note_check" CHECK ((("note" IS NULL) OR ("length"(TRIM(BOTH FROM "note")) > 0))),
    CONSTRAINT "training_reviews_signed_needs_note" CHECK (((NOT "signed") OR ("note" IS NOT NULL))),
    CONSTRAINT "training_reviews_stars_check" CHECK ((("stars" >= 1) AND ("stars" <= 5))),
    CONSTRAINT "training_reviews_tags_check" CHECK ((("tags" <@ ARRAY['useful'::"text", 'energising'::"text", 'clear'::"text", 'fun'::"text", 'too_fast'::"text", 'confusing'::"text", 'boring'::"text", 'hard'::"text"]) AND "company_os"."training_tags_are_distinct"("tags")))
);


--
-- Name: TABLE "training_reviews"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."training_reviews" IS 'One row is: one member''s ten-second review of one training they said they attended — stars, the load they felt, feeling tags and an optional note. Never read about one person for someone else (ADR 0016). [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "training_reviews"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_reviews"."id" IS 'Primary key.';


--
-- Name: COLUMN "training_reviews"."attendance_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_reviews"."attendance_id" IS 'The member''s attendance row (training_attendance) the review is about; one review per row.';


--
-- Name: COLUMN "training_reviews"."attendance_status"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_reviews"."attendance_status" IS 'Always attended: half of the foreign key onto training_attendance (id, status), so a review exists only on an attended row and that row cannot change to skipped while the review stands.';


--
-- Name: COLUMN "training_reviews"."stars"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_reviews"."stars" IS 'How useful the training was, 1 to 5. Giving the stars is what saves a review.';


--
-- Name: COLUMN "training_reviews"."load"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_reviews"."load" IS 'How much the training asked of the member, as they felt it; null when they did not say. Valid values: [too_little, about_right, too_much]';


--
-- Name: COLUMN "training_reviews"."tags"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_reviews"."tags" IS 'How it felt, any of a fixed set, none twice; empty when they picked none. Valid values: [useful, energising, clear, fun, too_fast, confusing, boring, hard]';


--
-- Name: COLUMN "training_reviews"."note"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_reviews"."note" IS 'An optional note for whoever runs the training; shown without a name unless signed, and without one once the member has left, signed or not.';


--
-- Name: COLUMN "training_reviews"."signed"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_reviews"."signed" IS 'True when the member chose to put their name on the note; only possible with a note. The name is dropped from what anyone sees once the member leaves (TR.11).';


--
-- Name: COLUMN "training_reviews"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_reviews"."created_at" IS 'When the review was first saved.';


--
-- Name: COLUMN "training_reviews"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_reviews"."updated_at" IS 'When the row last changed.';


