    "submitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "training_submissions_kind_check" CHECK (("kind" = ANY (ARRAY['written'::"text", 'upload'::"text", 'link'::"text", 'recording'::"text"]))),
    CONSTRAINT "training_submissions_shape" CHECK (((("kind" = 'written'::"text") AND ("text" IS NOT NULL) AND ("url" IS NULL) AND ("storage_path" IS NULL)) OR (("kind" = 'link'::"text") AND ("url" IS NOT NULL) AND ("text" IS NULL) AND ("storage_path" IS NULL)) OR (("kind" = ANY (ARRAY['upload'::"text", 'recording'::"text"])) AND ("storage_path" IS NOT NULL) AND ("text" IS NULL) AND ("url" IS NULL))))
);


