COMMENT ON COLUMN "company_os"."training_weekly_recaps"."id" IS 'Primary key.';


--
-- Name: COLUMN "training_weekly_recaps"."plan_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."plan_id" IS 'The plan (training_plans) the week is about.';


--
-- Name: COLUMN "training_weekly_recaps"."week_start"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."week_start" IS 'The Monday of the ISO week recapped; one row per plan per week.';


--
-- Name: COLUMN "training_weekly_recaps"."step"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."step" IS 'Where the run is: drafting (Claude writes it), waiting (the organiser may edit until send_after), sending, sent, held (the organiser stopped it), failed (the send errored; retried by the next tick). Valid values: [drafting, waiting, sending, sent, held, failed]';


--
-- Name: COLUMN "training_weekly_recaps"."draft"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."draft" IS 'What will be sent: {this_week, attendance, progress: [{person_id, md}], next_week}; null while drafting.';


--
-- Name: COLUMN "training_weekly_recaps"."instructor_note"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."instructor_note" IS 'The organiser''s own paragraph, added to the email; null when none.';


--
-- Name: COLUMN "training_weekly_recaps"."edited_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."edited_at" IS 'When the organiser last edited the draft or the note.';


--
-- Name: COLUMN "training_weekly_recaps"."edited_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."edited_by" IS 'The person (company_os.people) who last edited it.';


--
-- Name: COLUMN "training_weekly_recaps"."hold_reason"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."hold_reason" IS 'Why the organiser held it; set when step is held.';


--
-- Name: COLUMN "training_weekly_recaps"."send_after"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."send_after" IS 'When the routine sends it if the organiser has not; null before drafting finishes.';


--
-- Name: COLUMN "training_weekly_recaps"."sent_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."sent_at" IS 'When it was sent.';


--
-- Name: COLUMN "training_weekly_recaps"."sent_to"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."sent_to" IS 'Who it went to, as sent: an array of {person_id, email}.';


--
-- Name: COLUMN "training_weekly_recaps"."interaction_ids"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."interaction_ids" IS 'The interactions rows the sends were logged as, one per recipient.';


--
-- Name: COLUMN "training_weekly_recaps"."attempts"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."attempts" IS 'How many times sending has been tried; three failures raise an alarm.';


--
-- Name: COLUMN "training_weekly_recaps"."error"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."error" IS 'The last send error; null when none.';


--
-- Name: COLUMN "training_weekly_recaps"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."created_at" IS 'When the row was created.';


--
-- Name: COLUMN "training_weekly_recaps"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."training_weekly_recaps"."updated_at" IS 'When the row last changed.';


--
-- Name: trainings; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."trainings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "type_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "notes" "text",
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone NOT NULL,
    "organiser_id" "uuid" NOT NULL,
    "self_logged" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cancelled_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "plan_id" "uuid",
    "plan_state" "text" DEFAULT 'none'::"text" NOT NULL,
    "plan_reasoning" "text",
    "materials" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "recap" "jsonb",
    "recap_state" "text" DEFAULT 'none'::"text" NOT NULL,
    "recap_published_at" timestamp with time zone,
    "recap_published_by" "uuid",
    CONSTRAINT "trainings_ends_after_start" CHECK (("ends_at" > "starts_at")),
    CONSTRAINT "trainings_materials_array" CHECK (("jsonb_typeof"("materials") = 'array'::"text")),
    CONSTRAINT "trainings_plan_state_check" CHECK (("plan_state" = ANY (ARRAY['none'::"text", 'drafted'::"text", 'checked'::"text"]))),
    CONSTRAINT "trainings_recap_object" CHECK ((("recap" IS NULL) OR ("jsonb_typeof"("recap") = 'object'::"text"))),
    CONSTRAINT "trainings_recap_published_shape" CHECK ((("recap_state" = 'published'::"text") = ("recap_published_at" IS NOT NULL))),
    CONSTRAINT "trainings_recap_state_check" CHECK (("recap_state" = ANY (ARRAY['none'::"text", 'drafted'::"text", 'published'::"text"]))),
    CONSTRAINT "trainings_title_check" CHECK (("length"(TRIM(BOTH FROM "title")) > 0))
);


--
-- Name: TABLE "trainings"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON TABLE "company_os"."trainings" IS 'One row is: one training occurrence — one class, scrim, sharing session, conference day or course sitting — scheduled by an organiser or logged by a member for themselves. [transactional · People operations | tier 3 support | active]';


--
-- Name: COLUMN "trainings"."id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."id" IS 'Primary key.';


--
-- Name: COLUMN "trainings"."type_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."type_id" IS 'The kind of training (training_types).';


--
-- Name: COLUMN "trainings"."title"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."title" IS 'What the training is called, as its attendees see it.';


--
-- Name: COLUMN "trainings"."notes"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."notes" IS 'The organiser''s notes for attendees; editable after the training starts, unlike its time and people.';


--
-- Name: COLUMN "trainings"."starts_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."starts_at" IS 'When it starts. Once passed, only the title and notes may change.';


--
-- Name: COLUMN "trainings"."ends_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."ends_at" IS 'When it ends; the review window counts from here.';


--
-- Name: COLUMN "trainings"."organiser_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."organiser_id" IS 'The person (company_os.people) who put it on the record: the organiser, or the member who logged it.';


--
-- Name: COLUMN "trainings"."self_logged"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."self_logged" IS 'True when a member logged it for themselves; such a training has the member as its organiser and only attendee.';


--
-- Name: COLUMN "trainings"."created_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."created_at" IS 'When the row was inserted.';


--
-- Name: COLUMN "trainings"."updated_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."updated_at" IS 'When the row last changed.';


--
-- Name: COLUMN "trainings"."cancelled_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."cancelled_at" IS 'When the organiser cancelled it, before it started; a cancelled training asks nobody for their word.';


--
-- Name: COLUMN "trainings"."cancelled_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."cancelled_by" IS 'The person (company_os.people) who cancelled it.';


--
-- Name: COLUMN "trainings"."plan_id"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."plan_id" IS 'The plan (training_plans) this occurrence was published from; null for a single training or one a member logged for themselves.';


--
-- Name: COLUMN "trainings"."plan_state"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."plan_state" IS 'Where the session plan stands (English Program PR 3): none until the prep routine or the organiser writes blocks, drafted once Claude has, checked once the organiser has read it. Valid values: [none, drafted, checked]';


--
-- Name: COLUMN "trainings"."plan_reasoning"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."plan_reasoning" IS 'Claude''s one line on why it chose these blocks, for the organiser; null when the organiser wrote the plan by hand.';


--
-- Name: COLUMN "trainings"."materials"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."materials" IS 'Links the organiser attached for the session, shown to its learners: an array of {label, url}. Empty when none.';


--
-- Name: COLUMN "trainings"."recap"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."recap" IS 'The recap Claude drafted from the transcript (English Program PR 7): {covered, learners: [{person_id, md}], homework_suggestion}, each learner''s line addressed to that learner and shown to them alone; null until drafted.';


--
-- Name: COLUMN "trainings"."recap_state"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."recap_state" IS 'Where the recap stands: none, drafted (waiting for the organiser), published (the learners can see it). Valid values: [none, drafted, published]';


--
-- Name: COLUMN "trainings"."recap_published_at"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."recap_published_at" IS 'When the organiser published the recap.';


--
-- Name: COLUMN "trainings"."recap_published_by"; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON COLUMN "company_os"."trainings"."recap_published_by" IS 'The person (company_os.people) who published it.';


--
-- Name: vendors; Type: TABLE; Schema: company_os; Owner: -
--

CREATE TABLE "company_os"."vendors" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "type" "text" DEFAULT 'other'::"text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
