);


--
-- Name: client_identities; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."client_identities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "repo_id" "uuid",
    "git_email" "text",
    "github_login" "text",
    "label" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: delivered_additions; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."delivered_additions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "seq" bigint NOT NULL,
    "company_id" "uuid" NOT NULL,
    "hours" numeric(6,2) NOT NULL,
    "kind" "text" NOT NULL,
    "reason" "text" NOT NULL,
    "set_by_email" "text" NOT NULL,
    "set_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "delivered_additions_hours_check" CHECK (("hours" > (0)::numeric)),
    CONSTRAINT "delivered_additions_kind_check" CHECK (("kind" = ANY (ARRAY['meeting'::"text", 'deep_work'::"text", 'requirements'::"text", 'research'::"text", 'other'::"text"])))
);


--
-- Name: TABLE "delivered_additions"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON TABLE "htt"."delivered_additions" IS 'One addition to a client''s Delivered human tokens made by hand for work that did not run through Claude (meetings, deep work, requirement writing, research). Append-only; the Human Tokens band sums the rows into Delivered and Balance.';


--
-- Name: COLUMN "delivered_additions"."id"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."delivered_additions"."id" IS 'Primary key.';


--
-- Name: COLUMN "delivered_additions"."seq"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."delivered_additions"."seq" IS 'Monotonic identity sequence; orders the history unambiguously even when set_at ties.';


--
-- Name: COLUMN "delivered_additions"."company_id"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."delivered_additions"."company_id" IS 'FK to companies; the client company whose Delivered figure this row raises.';


--
-- Name: COLUMN "delivered_additions"."hours"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."delivered_additions"."hours" IS 'Human tokens added, in hours (the unit the band shows as Delivered); always positive.';


--
-- Name: COLUMN "delivered_additions"."kind"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."delivered_additions"."kind" IS 'What the work was: meeting, deep_work, requirements, research or other.';


--
-- Name: COLUMN "delivered_additions"."reason"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."delivered_additions"."reason" IS 'Free-text reason typed by the admin, shown under the Delivered tile and in the history.';


--
-- Name: COLUMN "delivered_additions"."set_by_email"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."delivered_additions"."set_by_email" IS 'Email of the Edge8-internal admin who added the row, taken from the verified session, never typed input.';


--
-- Name: COLUMN "delivered_additions"."set_at"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."delivered_additions"."set_at" IS 'When the addition was recorded.';


--
-- Name: delivered_additions_seq_seq; Type: SEQUENCE; Schema: htt; Owner: -
--

ALTER TABLE "htt"."delivered_additions" ALTER COLUMN "seq" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "htt"."delivered_additions_seq_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: engineer_keys; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."engineer_keys" (
    "key_id" "text" NOT NULL,
    "key_hash" "text" NOT NULL,
    "member" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "issued_at" "text" DEFAULT "to_char"(("now"() AT TIME ZONE 'utc'::"text"), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'::"text") NOT NULL,
    CONSTRAINT "engineer_keys_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'revoked'::"text"])))
);


--
-- Name: TABLE "engineer_keys"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON TABLE "htt"."engineer_keys" IS 'One issued engineer access key: the sha256 of an e8k_ credential a contributor''s machine holds, which mints GitHub tokens for git and authenticates that machine''s Claude Code telemetry. Mirrors the tracker''s own table shape so tracker.engineer_keys can become a view over it.';


--
-- Name: COLUMN "engineer_keys"."key_id"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."engineer_keys"."key_id" IS 'Primary key; the public half of the credential (e8k_<8 hex>), sent in full as e8k_<id>_<secret> and split back out on lookup.';


--
-- Name: COLUMN "engineer_keys"."key_hash"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."engineer_keys"."key_hash" IS 'sha256 hex of the whole presented key. The secret itself is shown once at issue and never stored, so a leak of this table does not yield a usable key.';


--
-- Name: COLUMN "engineer_keys"."member"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."engineer_keys"."member" IS 'Company email the key was issued to. A deliberate exception to the "reference people.id" rule: a key is issued by a separate service (edge8-github-app-tracker) before the holder necessarily exists in company_os.people, so callers resolve it to a person at read time through htt.resolve_contributor.';


--
-- Name: COLUMN "engineer_keys"."status"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."engineer_keys"."status" IS 'Whether the key still authenticates; revoking is how a machine or a departing contributor is cut off. Valid values: [active, revoked]';


--
-- Name: COLUMN "engineer_keys"."issued_at"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."engineer_keys"."issued_at" IS 'When the key was issued, as a UTC ISO-8601 string. Text rather than timestamptz to match the tracker''s schema exactly.';


--
-- Name: man_hour_entries; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."man_hour_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "person_id" "uuid",
    "company_id" "uuid" NOT NULL,
    "repo_id" "uuid",
    "primary_role" "text",
    "hours" numeric(6,2) NOT NULL,
    "occurred_on" "date" NOT NULL,
    "occurred_hour" smallint,
    "source" "text" NOT NULL,
    "description" "text",
    "rate_cents" integer,
    "currency" "text" DEFAULT 'AUD'::"text",
    "status" "text" DEFAULT 'recorded'::"text" NOT NULL,
    "started_at" timestamp with time zone,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "measured_hours" numeric(6,2),
    "evidence" "jsonb",
    "needs_review" boolean DEFAULT false NOT NULL,
    CONSTRAINT "man_hour_entries_occurred_hour_check" CHECK ((("occurred_hour" >= 0) AND ("occurred_hour" <= 23))),
    CONSTRAINT "man_hour_entries_source_check" CHECK (("source" = ANY (ARRAY['auto_session'::"text", 'manual'::"text"]))),
    CONSTRAINT "man_hour_entries_status_check" CHECK (("status" = ANY (ARRAY['recorded'::"text", 'approved'::"text", 'invoiced'::"text", 'paid'::"text", 'excluded'::"text"])))
);


--
-- Name: COLUMN "man_hour_entries"."measured_hours"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."man_hour_entries"."measured_hours" IS 'Hands-on hours the rule measured for this person, repo and day before the budget split; null on rows that predate the rule or were entered by hand.';


--
-- Name: COLUMN "man_hour_entries"."evidence"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."man_hour_entries"."evidence" IS 'What the measured figure rests on: session count, total measured across repos, the other repos'' shares, the budget and timezone applied.';


--
-- Name: COLUMN "man_hour_entries"."needs_review"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."man_hour_entries"."needs_review" IS 'True when the stored hours could not be measured (no session evidence) and a person should confirm or correct the day.';


--
-- Name: model_prices; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."model_prices" (
    "model" "text" NOT NULL,
    "input_usd_per_million" numeric(10,4) NOT NULL,
    "output_usd_per_million" numeric(10,4) NOT NULL,
    "cache_write_5m_multiplier" numeric(6,3) DEFAULT 1.25 NOT NULL,
    "cache_write_1h_multiplier" numeric(6,3) DEFAULT 2.0 NOT NULL,
    "cache_read_multiplier" numeric(6,3) DEFAULT 0.10 NOT NULL,
    "notes" "text",
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "model_prices_cache_read_multiplier_check" CHECK (("cache_read_multiplier" >= (0)::numeric)),
    CONSTRAINT "model_prices_cache_write_1h_multiplier_check" CHECK (("cache_write_1h_multiplier" >= (0)::numeric)),
    CONSTRAINT "model_prices_cache_write_5m_multiplier_check" CHECK (("cache_write_5m_multiplier" >= (0)::numeric)),
    CONSTRAINT "model_prices_input_usd_per_million_check" CHECK (("input_usd_per_million" >= (0)::numeric)),
    CONSTRAINT "model_prices_output_usd_per_million_check" CHECK (("output_usd_per_million" >= (0)::numeric))
);


--
-- Name: TABLE "model_prices"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON TABLE "htt"."model_prices" IS 'Anthropic list prices (USD per 1M tokens) used to price htt.token_entries usage components at read time. Service-role writes only, like every htt table.';


--
-- Name: project_goals; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."project_goals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "seq" bigint NOT NULL,
