    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: project_summaries; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."project_summaries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "repo_id" "uuid" NOT NULL,
