);


--
-- Name: pull_requests; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."pull_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "repo_id" "uuid" NOT NULL,
    "github_pr_id" bigint,
    "number" integer,
    "title" "text" NOT NULL,
    "author_login" "text",
    "author_person_id" "uuid",
    "url" "text",
    "state" "text" NOT NULL,
    "status" "text" DEFAULT 'tracked'::"text" NOT NULL,
    "opened_at" timestamp with time zone NOT NULL,
    "merged_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "head_branch" "text",
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "session_id" "text",
    "session_started_at" timestamp with time zone,
    "session_start_source" "text",
    CONSTRAINT "pull_requests_session_start_source_check" CHECK (("session_start_source" = 'commit-trailer'::"text")),
    CONSTRAINT "pull_requests_state_check" CHECK (("state" = ANY (ARRAY['open'::"text", 'merged'::"text", 'closed'::"text"]))),
    CONSTRAINT "pull_requests_status_check" CHECK (("status" = ANY (ARRAY['tracked'::"text", 'verified'::"text", 'disputed'::"text", 'excluded'::"text"])))
);


--
-- Name: COLUMN "pull_requests"."session_id"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."pull_requests"."session_id" IS 'Claude Code session UUID parsed from the PR body''s Claude-Session trailer line; groups PRs from one sitting. Null when the PR carries no (sane) trailer.';


--
-- Name: COLUMN "pull_requests"."session_started_at"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."pull_requests"."session_started_at" IS 'Session start instant parsed from the PR body''s Claude-Session-Start trailer line. Self-reported by the contributor machine; the sync rejects a start at or after opened_at. Capture-only today — no mint rule reads it yet.';


--
-- Name: COLUMN "pull_requests"."session_start_source"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."pull_requests"."session_start_source" IS 'Provenance of the session columns, so trailer rows never masquerade as telemetry-grade data. Valid values: [commit-trailer].';


--
-- Name: repos; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."repos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ai_program_id" "uuid" NOT NULL,
    "company_id" "uuid" NOT NULL,
    "slug" "text",
    "name" "text" NOT NULL,
    "github_repo" "text",
    "github_repo_id" bigint,
    "github_repo_aliases" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "roi_metric_name" "text",
    "roi_metric_unit" "text",
    "roi_metric_baseline" numeric,
    "roi_metric_target" numeric,
    "roi_metric_period" "text",
    "started_at" timestamp with time zone,
    "ended_at" timestamp with time zone,
    "status" "text" DEFAULT 'planned'::"text" NOT NULL,
    "last_synced_at" timestamp with time zone,
    "live_url" "text",
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "repos_roi_metric_period_check" CHECK (("roi_metric_period" = ANY (ARRAY['monthly'::"text", 'quarterly'::"text", 'annual'::"text"]))),
    CONSTRAINT "repos_roi_metric_unit_check" CHECK (("roi_metric_unit" = ANY (ARRAY['count'::"text", 'money'::"text", 'percent'::"text"]))),
    CONSTRAINT "repos_status_check" CHECK (("status" = ANY (ARRAY['planned'::"text", 'active'::"text", 'ramping'::"text", 'paused'::"text", 'complete'::"text", 'archived'::"text"])))
);


--
-- Name: COLUMN "repos"."ai_program_id"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."repos"."ai_program_id" IS 'FK to company_os.ai_programs: the AI Program this repo belongs to. A program owns any number of repos (X.1); every delivery figure is summed over them.';


--
-- Name: sync_runs; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."sync_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finished_at" timestamp with time zone,
    "projects_synced" integer DEFAULT 0 NOT NULL,
    "prs_upserted" integer DEFAULT 0 NOT NULL,
    "unattributed" integer DEFAULT 0 NOT NULL,
    "errors" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "backfill" boolean DEFAULT false NOT NULL
);


--
-- Name: token_allocations; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."token_allocations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "seq" bigint NOT NULL,
    "company_id" "uuid" NOT NULL,
    "tokens" numeric,
    "set_by_email" "text" NOT NULL,
    "set_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "kind" "text",
    "reason" "text",
    CONSTRAINT "token_allocations_kind_check" CHECK ((("kind" IS NULL) OR ("kind" = ANY (ARRAY['purchased'::"text", 'referral_credit'::"text", 'retreat'::"text", 'complimentary'::"text", 'invoiced'::"text", 'correction'::"text"])))),
    CONSTRAINT "token_allocations_tokens_check" CHECK (("tokens" >= (0)::numeric))
);


--
-- Name: COLUMN "token_allocations"."kind"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."token_allocations"."kind" IS 'Why this Bought figure was set: purchased, referral_credit, retreat, complimentary, invoiced or correction; null on rows imported before the admin control existed.';


--
-- Name: COLUMN "token_allocations"."reason"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."token_allocations"."reason" IS 'Free-text reason typed by the admin who set the figure, shown under the Bought tile and in the allocation history.';


--
-- Name: token_allocations_seq_seq; Type: SEQUENCE; Schema: htt; Owner: -
--

ALTER TABLE "htt"."token_allocations" ALTER COLUMN "seq" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "htt"."token_allocations_seq_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: token_entries; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."token_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "repo_id" "uuid",
    "pull_request_id" "uuid",
    "person_id" "uuid",
    "kind" "text" NOT NULL,
    "amount" bigint NOT NULL,
    "source" "text" NOT NULL,
    "occurred_at" timestamp with time zone NOT NULL,
    "occurred_on" "date",
    "status" "text" DEFAULT 'recorded'::"text" NOT NULL,
    "session_branch" "text",
    "session_id" "text",
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "model" "text",
    "input_tokens" bigint,
    "output_tokens" bigint,
    "cache_write_tokens" bigint,
    "cache_write_5m_tokens" bigint,
    "cache_write_1h_tokens" bigint,
    "cache_read_tokens" bigint,
    CONSTRAINT "token_entries_amount_check" CHECK (("amount" >= 0)),
    CONSTRAINT "token_entries_cache_read_tokens_check" CHECK ((("cache_read_tokens" IS NULL) OR ("cache_read_tokens" >= 0))),
    CONSTRAINT "token_entries_cache_write_1h_tokens_check" CHECK ((("cache_write_1h_tokens" IS NULL) OR ("cache_write_1h_tokens" >= 0))),
    CONSTRAINT "token_entries_cache_write_5m_tokens_check" CHECK ((("cache_write_5m_tokens" IS NULL) OR ("cache_write_5m_tokens" >= 0))),
    CONSTRAINT "token_entries_cache_write_tokens_check" CHECK ((("cache_write_tokens" IS NULL) OR ("cache_write_tokens" >= 0))),
    CONSTRAINT "token_entries_input_tokens_check" CHECK ((("input_tokens" IS NULL) OR ("input_tokens" >= 0))),
    CONSTRAINT "token_entries_kind_check" CHECK (("kind" = ANY (ARRAY['human'::"text", 'claude'::"text", 'app'::"text"]))),
    CONSTRAINT "token_entries_output_tokens_check" CHECK ((("output_tokens" IS NULL) OR ("output_tokens" >= 0))),
    CONSTRAINT "token_entries_source_check" CHECK (("source" = ANY (ARRAY['pr_commit'::"text", 'pr_review'::"text", 'planning'::"text", 'design'::"text", 'research'::"text", 'manual'::"text", 'session'::"text", 'app'::"text", 'effort-log'::"text"]))),
    CONSTRAINT "token_entries_status_check" CHECK (("status" = ANY (ARRAY['recorded'::"text", 'approved'::"text", 'disputed'::"text", 'excluded'::"text"])))
);


--
-- Name: COLUMN "token_entries"."model"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."token_entries"."model" IS 'Dominant model by API-call count for the session (telemetry schema v2). NULL = pre-v2 row. Priced at read time against htt.model_prices, never stored.';


--
-- Name: COLUMN "token_entries"."input_tokens"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."token_entries"."input_tokens" IS 'Uncached input tokens (schema v2). NULL = pre-v2 row. Priced at read time, never stored.';


--
-- Name: COLUMN "token_entries"."output_tokens"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."token_entries"."output_tokens" IS 'Output tokens incl. thinking (schema v2). NULL = pre-v2 row. Priced at read time, never stored.';


--
-- Name: COLUMN "token_entries"."cache_write_tokens"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."token_entries"."cache_write_tokens" IS 'Total prompt-cache write tokens (schema v2). May exceed the 5m + 1h split when the CLI gave no TTL breakdown; the remainder is priced as 5m at read time.';


--
-- Name: COLUMN "token_entries"."cache_write_5m_tokens"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."token_entries"."cache_write_5m_tokens" IS 'Prompt-cache writes with the 5-minute TTL (schema v2). 0 when the CLI gave no split.';


--
-- Name: COLUMN "token_entries"."cache_write_1h_tokens"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."token_entries"."cache_write_1h_tokens" IS 'Prompt-cache writes with the 1-hour TTL (schema v2). 0 when the CLI gave no split.';


--
-- Name: COLUMN "token_entries"."cache_read_tokens"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."token_entries"."cache_read_tokens" IS 'Prompt-cache read tokens (schema v2). Not part of amount for kind claude. Priced at read time, never stored.';


--
-- Name: work_sessions; Type: TABLE; Schema: htt; Owner: -
--

CREATE TABLE "htt"."work_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "repo_id" "uuid" NOT NULL,
    "person_id" "uuid",
    "session_id" "text" NOT NULL,
    "tool" "text",
    "started_at" timestamp with time zone,
    "ended_at" timestamp with time zone,
    "active_intervals" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "tokens_total" bigint DEFAULT 0 NOT NULL,
    "occurred_on" "date",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "human_turns" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL
);


--
-- Name: TABLE "work_sessions"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON TABLE "htt"."work_sessions" IS 'One Claude Code session on one tracked repo: when it ran, the intervals the contributor was actually active, and its token total. The raw input of the human-hours rule.';


--
-- Name: COLUMN "work_sessions"."id"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."id" IS 'Primary key.';


--
-- Name: COLUMN "work_sessions"."company_id"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."company_id" IS 'FK to companies; the repo''s owning client, denormalized for per-company reads.';


--
-- Name: COLUMN "work_sessions"."repo_id"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."repo_id" IS 'FK to htt.repos; the repo the session worked on.';


--
-- Name: COLUMN "work_sessions"."person_id"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."person_id" IS 'FK to people; the contributor, resolved from their git email; null when unknown.';


--
-- Name: COLUMN "work_sessions"."session_id"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."session_id" IS 'Claude Code session UUID; the idempotency key, so a re-ingest updates rather than duplicates.';


--
-- Name: COLUMN "work_sessions"."tool"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."tool" IS 'The tool that produced the session, e.g. claude-code.';


--
-- Name: COLUMN "work_sessions"."started_at"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."started_at" IS 'First message instant.';


--
-- Name: COLUMN "work_sessions"."ended_at"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."ended_at" IS 'Last message instant.';


--
-- Name: COLUMN "work_sessions"."active_intervals"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."active_intervals" IS 'JSON array of {start, end} ISO instants during which messages flowed without a 30 minute gap; hands-on time is their union.';


--
-- Name: COLUMN "work_sessions"."tokens_total"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."tokens_total" IS 'Deduplicated input + output + cache-creation tokens the session used.';


--
-- Name: COLUMN "work_sessions"."occurred_on"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."occurred_on" IS 'The session''s start day in the contributor''s timezone.';


--
-- Name: COLUMN "work_sessions"."created_at"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."created_at" IS 'Row creation time.';


--
-- Name: COLUMN "work_sessions"."updated_at"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."updated_at" IS 'Last modification time.';


--
-- Name: COLUMN "work_sessions"."human_turns"; Type: COMMENT; Schema: htt; Owner: -
--

COMMENT ON COLUMN "htt"."work_sessions"."human_turns" IS 'JSON array of {t, branch, run_end}: the instant and git branch of every line the contributor typed (never AI or tool output) and when the AI went quiet after it. The hours rule (v2) builds 10-minute runs from these, unions them across the person''s sessions and repos for the day, and apportions the day by turn share. Empty for sessions recorded before edge8-telemetry 1.4.0.';


