insert into company_os.training_types (name, sort_order)
select v.name, v.sort_order
from (values
  ('Class', 10),
  ('Online course', 20),
  ('Conference', 30),
  ('Sharing session', 40),
  ('Workshop', 50),
  ('Practice', 60)
) as v (name, sort_order)
where not exists (
  select 1 from company_os.training_types t where lower(t.name) = lower(v.name) and t.archived_at is null
);

